/**
 * 街头工作定义（15+种）
 *
 * 每项工作格式:
 * {
 *   id, name, desc, icon,                    // 显示
 *   location: '...',                          // 需要在此地点
 *   requirements: { ... },                    // 属性/技能/年龄要求
 *   effects: { ... },                         // 执行后属性变化
 *   payCalc(state),                           // 收入计算函数（引用 state）
 *   risk: { injury, illness },                // 风险概率
 *   startupCost: 0,                           // 启动资金（可选）
 * }
 */

const STREET_JOBS = [
  // ====== 城中村 ======
  {
    id: "waste_recycling",
    name: "废品回收",
    desc: "走街串巷收废纸板、废金属、废塑料，转手卖给回收站。脏活累活但门槛最低。",
    icon: "♻️",
    location: "slum",
    requirements: { minAge: 16, maxAge: 65 },
    effects: {
      fatigue: 22,
      hygiene: -15,
      happiness: -5,
      physiqueXp: 2,
      agilityXp: 1,
    },
    payCalc(state) {
      const base = 20 + Math.random() * 35;
      const multi = 1 + state.skills.sales.level * 0.005;
      return Math.floor(base * Math.min(multi, 2));
    },
    risk: { injury: 0.04, illness: 0.03 },
  },

  // ====== 商业区 — 摆摊 ======
  {
    id: "street_vending_food",
    name: "摆摊卖小吃",
    desc: "在街边支个小摊卖烤串、煎饼果子。手艺越好，回头客越多。",
    icon: "🍢",
    location: "commercialDist",
    requirements: { minAge: 16, maxAge: 60 },
    effects: { fatigue: 16, hygiene: -5, happiness: 3, cookingXp: 4 },
    payCalc(state) {
      const skillBonus = state.skills.cooking.level * 0.8;
      return Math.floor(45 + skillBonus + Math.random() * 35);
    },
    startupCost: 50,
    risk: {},
  },
  {
    id: "street_vending_goods",
    name: "摆摊卖小商品",
    desc: "从批发市场进些日用品、小电子产品，在商业区摆摊赚差价。",
    icon: "🧦",
    location: "commercialDist",
    requirements: { minAge: 16, maxAge: 60 },
    effects: { fatigue: 14, happiness: 2, salesXp: 3 },
    payCalc(state) {
      const skillBonus = state.skills.sales.level * 0.6;
      return Math.floor(38 + skillBonus + Math.random() * 28);
    },
    startupCost: 30,
    risk: { injury: 0.02 },
  },

  // ====== 建筑工地 ======
  {
    id: "manual_labor_construction",
    name: "建筑工地苦力",
    desc: "在工地搬砖、扛水泥、推砂石。纯体力活，工资日结不拖欠。",
    icon: "🧱",
    location: "construction",
    requirements: { physique: 20, minAge: 18, maxAge: 55 },
    effects: { fatigue: 38, hygiene: -22, physiqueXp: 6, happiness: -10 },
    payCalc(state) {
      return Math.floor(65 + state.player.physique * 0.5 + Math.random() * 30);
    },
    risk: { injury: 0.1, illness: 0.04 },
  },
  {
    id: "skilled_labor_construction",
    name: "工地技术工",
    desc: "会手艺的工地活——水电安装、木工、钢筋工。收入比苦力高不少。",
    icon: "🔨",
    location: "construction",
    requirements: {
      physique: 25,
      repair: 15,
      agility: 20,
      minAge: 20,
      maxAge: 60,
    },
    effects: { fatigue: 28, hygiene: -12, physiqueXp: 3, repairXp: 5 },
    payCalc(state) {
      return Math.floor(
        120 +
          state.skills.repair.level * 1.2 +
          state.player.physique * 0.25 +
          Math.random() * 35,
      );
    },
    risk: { injury: 0.05 },
  },

  // ====== 工业区 — 工厂 ======
  {
    id: "factory_work_assembly",
    name: "工厂流水线",
    desc: "在电子厂做装配工。机械重复手不停，但收入稳定包吃住。",
    icon: "🏭",
    location: "factoryZone",
    requirements: { agility: 15, minAge: 18, maxAge: 45 },
    effects: {
      fatigue: 28,
      hygiene: -5,
      happiness: -15,
      mental: -2,
      agilityXp: 3,
    },
    payCalc(state) {
      return Math.floor(80 + state.player.agility * 0.3 + Math.random() * 18);
    },
    risk: { injury: 0.03, illness: 0.02 },
  },
  {
    id: "factory_overtime",
    name: "工厂加班",
    desc: "晚上加班赶订单，加班费可观，但这钱是用身体换的。",
    icon: "🌙",
    location: "factoryZone",
    requirements: { agility: 15, physique: 18, minAge: 18, maxAge: 45 },
    effects: { fatigue: 42, hygiene: -3, happiness: -20, mental: -4 },
    payCalc(state) {
      return Math.floor(115 + state.player.physique * 0.4 + Math.random() * 25);
    },
    risk: { illness: 0.06 },
  },

  // ====== 商业区 — 餐饮服务 ======
  {
    id: "food_stall",
    name: "餐饮摊贩",
    desc: "租个小摊位卖早餐、夜宵。辛苦但利润不错，手艺好能赚更多。",
    icon: "🍜",
    location: "commercialDist",
    requirements: { cooking: 10, minAge: 18, maxAge: 55 },
    effects: { fatigue: 22, hygiene: -8, cookingXp: 5, happiness: 2 },
    payCalc(state) {
      return Math.floor(
        95 + state.skills.cooking.level * 1.5 + Math.random() * 50,
      );
    },
    startupCost: 200,
    risk: { injury: 0.02 },
  },

  // ====== 商业区 — 服务业 ======
  {
    id: "barber",
    name: "理发师",
    desc: "在街边理发店做理发师。手艺活，环境干净，收入稳定。",
    icon: "💇",
    location: "commercialDist",
    requirements: { agility: 20, sales: 5, minAge: 18, maxAge: 60 },
    effects: { fatigue: 16, happiness: 5, agilityXp: 2, salesXp: 3 },
    payCalc(state) {
      return Math.floor(
        48 +
          state.player.agility * 0.25 +
          state.skills.sales.level * 0.5 +
          Math.random() * 32,
      );
    },
    risk: {},
  },
  {
    id: "cleaning_service",
    name: "保洁/家政",
    desc: "帮人打扫卫生、收拾屋子。活不重，收入不高但稳定。",
    icon: "🧹",
    location: "commercialDist",
    requirements: { minAge: 18, maxAge: 55 },
    effects: { fatigue: 20, hygiene: -8, physiqueXp: 2 },
    payCalc(state) {
      return Math.floor(40 + state.player.physique * 0.15 + Math.random() * 25);
    },
    risk: {},
  },
  {
    id: "repair_service",
    name: "家电维修",
    desc: "帮人修家电、手机、电脑。技术活，口碑好了收入越来越高。",
    icon: "🔧",
    location: "commercialDist",
    requirements: { repair: 20, intelligence: 20, minAge: 18, maxAge: 65 },
    effects: { fatigue: 14, repairXp: 5, happiness: 8 },
    payCalc(state) {
      return Math.floor(
        65 + state.skills.repair.level * 2.0 + Math.random() * 42,
      );
    },
    risk: {},
  },

  // ====== 工业区 ======
  {
    id: "security_guard",
    name: "保安",
    desc: "在工厂或小区看大门。活不多，能坐着，但工资不高。",
    icon: "👮",
    location: "factoryZone",
    requirements: { minAge: 20, maxAge: 55 },
    effects: { fatigue: 10, happiness: -3, physiqueXp: 1 },
    payCalc(state) {
      return Math.floor(32 + Math.random() * 18);
    },
    risk: {},
  },
  {
    id: "warehouse_worker",
    name: "仓库搬运",
    desc: "在物流仓库搬货、分拣包裹。体力消耗大但按件计酬。",
    icon: "📦",
    location: "factoryZone",
    requirements: { physique: 18, minAge: 18, maxAge: 50 },
    effects: { fatigue: 32, hygiene: -10, physiqueXp: 4 },
    payCalc(state) {
      return Math.floor(58 + state.player.physique * 0.4 + Math.random() * 25);
    },
    risk: { injury: 0.05 },
  },

  // ====== 大学城 ======
  {
    id: "school_maintenance",
    name: "学校勤杂工",
    desc: "在学校做维修、绿化、清洁等杂活。环境好，氛围轻松。",
    icon: "🏫",
    location: "school",
    requirements: { minAge: 18, maxAge: 60 },
    effects: { fatigue: 16, hygiene: -5, happiness: 8, repairXp: 2 },
    payCalc(state) {
      return Math.floor(42 + Math.random() * 22);
    },
    risk: {},
  },
  {
    id: "package_delivery",
    name: "校园/社区快递",
    desc: "帮学生和社区居民收发快递包裹。腿脚麻利跑得快是核心竞争力。",
    icon: "📬",
    location: "school",
    requirements: { agility: 15, minAge: 18, maxAge: 50 },
    effects: { fatigue: 24, hygiene: -5, agilityXp: 4 },
    payCalc(state) {
      return Math.floor(40 + state.player.agility * 0.4 + Math.random() * 25);
    },
    risk: { injury: 0.03 },
  },
  {
    id: "tutoring",
    name: "家教",
    desc: "给中小学生辅导功课。知识就是金钱，智力越高收入越好。",
    icon: "📖",
    location: "school",
    requirements: { intelligence: 30, minAge: 18, maxAge: 65 },
    effects: { fatigue: 12, intelligenceXp: 3, englishXp: 2, happiness: 10 },
    payCalc(state) {
      return Math.floor(
        62 +
          state.player.intelligence * 0.45 +
          state.skills.english.level * 0.3 +
          Math.random() * 32,
      );
    },
    risk: {},
  },

  // ====== 商业区 — 更多 ======
  {
    id: "delivery_rider",
    name: "外卖骑手",
    desc: "平台众包骑手，接单送餐。多劳多得，风里来雨里去。",
    icon: "🛵",
    location: "commercialDist",
    requirements: { agility: 22, minAge: 18, maxAge: 45 },
    effects: { fatigue: 34, hygiene: -8, agilityXp: 5, happiness: -5 },
    payCalc(state) {
      return Math.floor(50 + state.player.agility * 0.7 + Math.random() * 50);
    },
    risk: { injury: 0.07 },
  },
  {
    id: "street_performer",
    name: "街头卖艺",
    desc: "在天桥或广场表演才艺。脸皮要厚，观众打赏全看心情。",
    icon: "🎸",
    location: "commercialDist",
    requirements: { mental: 30, minAge: 16, maxAge: 60 },
    effects: { fatigue: 12, happiness: 18, mental: 2, fame: 3 },
    payCalc(state) {
      return Math.floor(
        18 +
          state.player.mental * 0.2 +
          state.status.fame * 0.3 +
          Math.random() * 42,
      );
    },
    risk: {},
  },
];

/** 根据 ID 获取工作定义 */
function getJobById(jobId) {
  return STREET_JOBS.find((j) => j.id === jobId) || null;
}

/**
 * NPC 定义 — 街头生活中遇到的各色人物
 */

const NPCS = [
  {
    id: "aunt_wang",
    name: "王大婶",
    role: "房东",
    location: "slum",
    desc: "城中村的房东，说话嗓门大但心地不坏。偶尔会介绍些零活。",
    talkLines: [
      "小伙子，这个月房租该交了啊！",
      "看你挺勤快的，工地上缺人要不要去试试？",
      "年轻人要有志气，别一辈子收废品。",
    ],
    giftPrefers: ["fruits", "daily_use"],
  },
  {
    id: "boss_li",
    name: "李工头",
    role: "包工头",
    location: "construction",
    desc: "建筑工地的包工头，手上活多。关系好了会给好活。",
    talkLines: ["今天活多，加紧干！", "小心点，安全第一。", "干得好有奖金。"],
    giftPrefers: ["cigarettes", "beer"],
  },
  {
    id: "sister_zhang",
    name: "张姐",
    role: "中介",
    location: "commercialDist",
    desc: "人力资源中介，认识各行各业的人。帮她跑腿可以提升关系。",
    talkLines: [
      "我这边有几个好工作，你要不要看看？",
      "做服务业态度最重要。",
      "多考几个证，好工作不愁。",
    ],
    giftPrefers: ["clothing", "snacks"],
  },
  {
    id: "old_zhou",
    name: "老周",
    role: "收废品老人",
    location: "slum",
    desc: "在城中村收了几十年废品的老前辈。知道废品行情的门道。",
    talkLines: [
      "废金属最近涨了，赶紧多收点。",
      "收废品虽然脏，但也是一门生意经。",
      "年轻人脑子活，学学怎么挑好货。",
    ],
    giftPrefers: ["beer", "instant_noodles"],
  },
  {
    id: "xiao_mei",
    name: "小美",
    role: "大学生",
    location: "school",
    desc: "大学城的贫困生，周末做家教赚生活费。",
    talkLines: [
      "你知道哪里还有家教的机会吗？",
      "我英语还不错，可以教初中生。",
      "毕业后想去大厂，得先积累经验。",
    ],
    giftPrefers: ["fruits", "snacks"],
  },
  {
    id: "chef_chen",
    name: "陈师傅",
    role: "大厨",
    location: "commercialDist",
    desc: "商业区小有名气的厨师，手艺了得。想学烹饪可以找他。",
    talkLines: [
      "做菜讲究火候，做人讲究分寸。",
      "来尝尝我新研制的配方。",
      "你有点天分，要不要学两手？",
    ],
    giftPrefers: ["beer", "vegetables"],
  },
];

/** 获取NPC */
function getNpcById(npcId) {
  return NPCS.find((n) => n.id === npcId) || null;
}

/** 获取当前地点的NPC */
function getNpcsAtLocation(locKey) {
  return NPCS.filter((n) => n.location === locKey);
}

/** 获取好感度描述 */
function getAffinityLabel(affinity) {
  if (affinity >= 80) return "❤️ 挚友";
  if (affinity >= 60) return "😊 好友";
  if (affinity >= 30) return "🙂 熟人";
  if (affinity >= 0) return "👤 初识";
  if (affinity >= -30) return "😐 冷淡";
  return "😠 厌恶";
}

/**
 * 证书/技能训练定义
 * 可在培训中心考取
 */

const CERTIFICATES = [
  {
    id: "construction_safety",
    name: "建筑安全证",
    desc: "进入建筑工地的必要条件，减少受伤风险50%",
    requirements: { cash: 300, intelligence: 20 },
    effects: { injuryReduction: 0.5 },
    examPassRate: 0.85,
  },
  {
    id: "coding_basic",
    name: "编程基础证书",
    desc: "证明你具备基本编程能力，进入职场的重要敲门砖",
    requirements: { cash: 500, intelligence: 35 },
    effects: { codingXp: 50, intelligence: 2 },
    examPassRate: 0.65,
  },
  {
    id: "accounting_cert",
    name: "会计从业证",
    desc: "可以做会计类工作，收入稳定",
    requirements: { cash: 400, intelligence: 30 },
    effects: { accountingXp: 40, intelligence: 1 },
    examPassRate: 0.7,
  },
  {
    id: "welding_cert",
    name: "焊工证",
    desc: "特种作业证书，焊工工资高",
    requirements: { cash: 600, physique: 35 },
    effects: { weldingXp: 50, physique: 2 },
    examPassRate: 0.75,
  },
  {
    id: "driver_license",
    name: "驾照",
    desc: "可以开车，解锁送货司机等高收入工作",
    requirements: { cash: 800, agility: 25 },
    effects: { drivingXp: 40, agility: 1 },
    examPassRate: 0.6,
  },
  {
    id: "english_cert",
    name: "英语四级证书",
    desc: "证明英语水平，对外企和家教有帮助",
    requirements: { cash: 350, intelligence: 40 },
    effects: { englishXp: 60, intelligence: 2 },
    examPassRate: 0.55,
  },
  {
    id: "electrician_cert",
    name: "电工证",
    desc: "家电维修和工业电工的必备证书",
    requirements: { cash: 500, repair: 20, intelligence: 25 },
    effects: { electricianXp: 50, repair: 3 },
    examPassRate: 0.7,
  },
  {
    id: "management_cert",
    name: "管理师证书",
    desc: "职场晋升的加分项",
    requirements: { cash: 800, intelligence: 45 },
    effects: { managementXp: 50, intelligence: 3 },
    examPassRate: 0.5,
  },
];

/** 获取证书定义 */
function getCertificateById(certId) {
  return CERTIFICATES.find((c) => c.id === certId) || null;
}

/** 获取玩家可考的证书 */
function getAvailableCertificates(state) {
  return CERTIFICATES.filter((cert) => {
    if (state.certificates.includes(cert.id)) return false; // 已拥有
    const p = state.player;
    const req = cert.requirements;
    if (req.intelligence && p.intelligence < req.intelligence) return false;
    if (req.physique && p.physique < req.physique) return false;
    if (req.repair && state.skills.repair.level < req.repair) return false;
    if (req.agility && p.agility < req.agility) return false;
    return true;
  });
}

