577	      }
578	      var luck = Math.random();
579	      var baseEarned = 0;
580	      var xpGain = 0;
581	      if (luck < 0.25) {
582	        // 大赚
583	        baseEarned = 150 + Math.floor(Math.random() * 200);
584	        xpGain = 8 + Math.floor(Math.random() * 7); // 8~14 XP
585	        st.status.fame = Math.min(100, st.status.fame + 2);
586	      } else if (luck < 0.7) {
587	        // 小赚
588	        baseEarned = 30 + Math.floor(Math.random() * 90);
589	        xpGain = 4 + Math.floor(Math.random() * 5); // 4~8 XP
590	      } else if (luck < 0.85) {
591	        // 勉强回本
592	        baseEarned = 180 + Math.floor(Math.random() * 40);
593	        xpGain = 2 + Math.floor(Math.random() * 3); // 2~4 XP
594	        StateManager.addMessage("🏪 摆摊勉强度日，赚了点辛苦钱。", "warning");
595	      } else {
596	        // 亏了
597	        StateManager.addMessage("🏪 摆摊失败！货没卖掉，城管还罚了款。", "danger");
598	        st.resources.cash = Math.max(0, st.resources.cash - 50);
599	        st.needs.happiness = Math.max(0, st.needs.happiness - 5);
600	        xpGain = 1 + Math.floor(Math.random() * 3); // 1~3 XP（失败也能学点教训）
601	      }
602	      // 应用销售技能收益倍率
603	      var earned = Math.floor(baseEarned * salesMultiplier);
604	      if (earned > 0) {
605	        st.resources.cash += earned;
606	        st.resources.totalEarned += earned;
607	      }
608	      // 销售技能经验
609	      if (xpGain > 0) {
610	        st.skills.sales.xp = (st.skills.sales.xp || 0) + xpGain;
611	        // 检查升级
612	        while (st.skills.sales.xp >= (st.skills.sales.level + 1) * 120 && st.skills.sales.level < 100) {
613	          st.skills.sales.xp -= (st.skills.sales.level + 1) * 120;
614	          st.skills.sales.level++;
615	          if (st.player.agility < 100) st.player.agility = Math.min(100, st.player.agility + 1);
616	          StateManager.addMessage('⭐ 销售技能升级到 Lv.' + st.skills.sales.level + '！', 'success');
617	        }
618	      }
619	      if (earned > 0) {
620	        StateManager.addMessage('🏪 摆摊收入 ¥' + earned + '（销售Lv.' + salesLvl + '，倍率×' + salesMultiplier.toFixed(2) + '）📚销售+' + xpGain + 'XP', 'success');
621	      }
622	      consumeAP(20);
623	    },
624	  });
625	}
626	
627	/** 汇款模态框 */
628	function showRemitModal() {
629	  const state = StateManager.getState();
630	  showModal({
631	    title: "💌 给家里汇款",
632	    body: `<p>当前现金: ¥${state.resources.cash.toLocaleString()}</p>
633	           <p style="font-size:11px;color:var(--text-secondary);">每汇 100 元，心情+3，名气+0.5。</p>
634	           <label>汇款金额: <input id="remit-amount" type="number" min="100" max="${state.resources.cash}" value="200" style="width:100%;padding:8px;margin-top:8px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;"></label>`,
635	    buttons: [
636	      { text: "取消", cls: "", callback: () => {} },
637	      {
638	        text: "汇款",
639	        cls: "btn-primary",
640	        callback: () => {
641	          const amt = Math.max(
642	            0,
643	            Math.min(
644	              state.resources.cash,
645	              parseInt(document.getElementById("remit-amount")?.value || 0),
646	            ),
647	          );
648	          if (amt < 100) {
649	            StateManager.addMessage("💌 至少汇 100 块。", "warning");
650	            return;
651	          }
652	          state.resources.cash -= amt;
653	          state.needs.happiness = Math.min(
654	            100,
655	            state.needs.happiness + (amt / 100) * 3,
656	          );
657	          state.status.fame = Math.min(
658	            100,
659	            state.status.fame + (amt / 100) * 0.5,
660	          );
661	          StateManager.addMessage(
662	            `💌 给家里汇了 ¥${amt.toLocaleString()}，爸妈很高兴。`,
663	            "success",
664	          );
665	          document.querySelector(".modal-overlay")?.remove();
666	          renderAll();
667	        },
668	      },
669	    ],
670	  });
671	}
672	
673	/** 余额宝模态框 */
674	function showYuEBaoModal() {
675	  const state = StateManager.getState();
676	  const yue = state.flags.yuEBao || 0;
677	  const todayInterest = Math.floor(yue * 0.0001);
678	  showModal({
679	    title: "💰 余额宝理财",
680	    body: `
681	      <p>当前余额宝: <strong style="color:var(--success);">¥${yue.toLocaleString()}</strong></p>
682	      <p>今日收益预估: <strong>+¥${todayInterest}</strong>（日息 0.01%）</p>
683	      <p>现金: ¥${state.resources.cash.toLocaleString()}</p>
684	      <label>转入金额: <input id="yue-amount" type="number" min="100" max="${state.resources.cash}" value="${Math.floor(state.resources.cash)}" style="width:100%;padding:8px;margin-top:8px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;"></label>
685	    `,
686	    buttons: [
687	      { text: "取消", cls: "", callback: () => {} },
688	      {
689	        text: "全部转出",
690	        cls: "btn-warning",
691	        callback: () => {
692	          state.resources.cash += yue;
693	          state.flags.yuEBao = 0;
694	          StateManager.addMessage(
695	            `💰 从余额宝转出 ¥${yue.toLocaleString()}。`,
696	            "info",
697	          );
698	          document.querySelector(".modal-overlay")?.remove();
699	          renderAll();
700	        },
701	      },
702	      {
703	        text: "确认转入",
704	        cls: "btn-success",
705	        callback: () => {
706	          const amt = Math.max(
707	            0,
708	            Math.min(
709	              state.resources.cash,
710	              parseInt(document.getElementById("yue-amount")?.value || 0),
711	            ),
712	          );
713	          if (amt < 100) {
714	            StateManager.addMessage("💰 至少转入 100 块。", "warning");
715	            return;
716	          }
717	          state.resources.cash -= amt;
718	          state.flags.yuEBao = (state.flags.yuEBao || 0) + amt;
719	          StateManager.addMessage(
720	            `💰 转入余额宝 ¥${amt.toLocaleString()}。`,
721	            "success",
722	          );
723	          document.querySelector(".modal-overlay")?.remove();
724	          renderAll();
725	        },
726	      },
727	    ],
728	  });
729	}
730	
731	/** 给 main.js 调用的统一入口 */
732	function addExtraActions(state, actions) {
733	  if (state.player.phase === "street") {
734	    addStreetExtras(state, actions);
735	  }
736	  // 余额宝每日利息
737	  if (state.flags.yuEBao > 0) {
738	    const interest = Math.floor(state.flags.yuEBao * 0.0001);
739	    if (interest > 0) {
740	      state.flags.yuEBao += interest;
741	    }
742	  }
743	  // 保险检查
744	  if (
745	    state.flags.hasInsurance &&
746	    state.flags.insuranceExpire < state.player.day
747	  ) {
748	    state.flags.hasInsurance = false;
749	    StateManager.addMessage("🛡️ 你的保险到期了，记得续保。", "info");
750	  }
751	  if (state.flags.hasInsurance && (state.status.injured || state.status.sick)) {
752	    if (!state.flags._insurancePaidThisCycle) {
753	      state.resources.cash += 500;
754	      state.flags._insurancePaidThisCycle = true;
755	      StateManager.addMessage("🛡️ 保险赔付了 ¥500！", "success");
756	    }
757	  }
758	  if (!state.status.injured && !state.status.sick) {
759	    state.flags._insurancePaidThisCycle = false;
760	  }
761	}
