1	/**
2	 * 技能→系统加成映射 — 技能影响多系统（吃饭/旅行/工作/银行/职场等）
3	 *
4	 * 设计理念：每项技能不仅解锁工作，还对相关的游戏系统产生渐进式加成，
5	 * 让技能培养有持续正反馈，形成"学以致用"的良性循环。
6	 */
7	
8	/** cooking技能 → 自己做饭折扣（技能越高做饭越划算） */
9	function getCookingDiscount(cookingLevel) {
10	  // 自己做饭花费 = 基础花费 * (1 - cookingLevel * 0.008)
11	  // level 0: 全额, level 50: 6折, level 100: 2折（最低保底3折）
12	  return Math.min(0.7, cookingLevel * 0.008);
13	}
14	
15	/** driving技能 → 旅行AP减免 */
16	function getTravelApReduction(drivingLevel) {
17	  // 每20级减1AP，最多减5AP
18	  return Math.min(5, Math.floor(drivingLevel / 20));
19	}
20	
21	/** english技能 → 家教额外收入加成 */
22	function getTutoringBonus(englishLevel) {
23	  return englishLevel * 0.3;
24	}
25	
26	/** accounting技能 → 银行利率加成 */
27	function getBankRateBonus(accountingLevel) {
28	  // 每年最多+5%（日息约+0.00014），100级满分
29	  return accountingLevel * 0.0005;
30	}
31	
32	/** electrician技能 → 工厂类工作收入加成百分比 */
33	function getFactoryBonus(electricianLevel) {
34	  return electricianLevel * 0.005;
35	}
36	
37	/** welding技能 → 建筑类工作收入加成百分比 */
38	function getConstructionBonus(weldingLevel) {
39	  return weldingLevel * 0.008;
40	}
41	
42	/** coding技能 → 职场能力加成（每10级+2点ability） */
43	function getCorpAbilityBonus(codingLevel) {
44	  return Math.floor(codingLevel / 10) * 2;
45	}
46	
47	/** management技能 → 职场向上管理加成（每10级+1点upwardMgmt） */
48	function getCorpUpwardBonus(managementLevel) {
49	  return Math.floor(managementLevel / 10) * 1;
50	}
51	
52	/** repair技能 → 装备/工具效果加成（百分比） */
53	function getRepairBonus(repairLevel) {
54	  return repairLevel * 0.005;
55	}
56	
57	/** sales技能 → 交易买卖价格优势 */
58	function getSalesTradeDiscount(salesLevel) {
59	  // 买入折扣：最高15%
60	  return Math.min(0.15, salesLevel * 0.002);
61	}
62	function getSalesTradePremium(salesLevel) {
63	  // 卖出溢价：最高15%
64	  return Math.min(0.15, salesLevel * 0.002);
65	}
66	
67	/**
68	 * 工作后分发技能经验值（与工作类型关联）
69	 * 返回字符串描述获得了什么XP
70	 */
71	function grantJobSkillXp(jobId, state) {
72	  var job = typeof STREET_JOBS !== 'undefined'
73	    ? STREET_JOBS.find(function(j) { return j.id === jobId; })
74	    : null;
75	  if (!job) return '';
76	
77	  var xpMap = {
78	    // 烹饪相关工作 → cooking XP
79	    street_vending_food: { skill: 'cooking', min: 2, max: 5 },
80	    food_stall: { skill: 'cooking', min: 3, max: 7 },
81	    // 销售相关工作 → sales XP
82	    street_vending_goods: { skill: 'sales', min: 2, max: 5 },
83	    barber: { skill: 'sales', min: 2, max: 4 },
84	    // 维修相关工作 → repair XP
85	    skilled_labor_construction: { skill: 'repair', min: 3, max: 6 },
86	    repair_service: { skill: 'repair', min: 4, max: 8 },
87	    // 英语相关工作 → english XP
88	    tutoring: { skill: 'english', min: 2, max: 4 },
89	    // 驾驶相关工作 → driving XP
90	    delivery_rider: { skill: 'driving', min: 3, max: 6 },
91	  };
92	
93	  var entry = xpMap[jobId];
94	  if (!entry) return '';
95	
96	  var sk = state.skills[entry.skill];
97	  if (!sk) return '';
98	
99	  var xpGain = entry.min + Math.floor(Math.random() * (entry.max - entry.min + 1));
100	
101	  // 情绪加成技能XP（happy时1.5倍，depressed时0.3倍）
102	  var emoMod = typeof getEmotionWorkModifier === 'function'
103	    ? getEmotionWorkModifier(state)
104	    : { skillXp: 1.0 };
105	  xpGain = Math.round(xpGain * emoMod.skillXp);
106	
107	  // 智力高有一定加成
108	  var intBonus = Math.floor((state.player.intelligence || 0) / 30);
109	  xpGain += intBonus;
110	
111	  sk.xp = (sk.xp || 0) + xpGain;
112	
113	  // 检查升级
114	  var leveledUp = false;
115	  while (sk.xp >= (sk.level + 1) * 120 && sk.level < 100) {
116	    sk.xp -= (sk.level + 1) * 120;
117	    sk.level++;
118	    leveledUp = true;
119	    // 升级提升关联属性（微量）
120	    applySkillLevelUpBonus(entry.skill, state);
121	  }
122	
123	  var msg = '📚 ' + getSkillChineseName(entry.skill) + ' +' + xpGain + 'XP';
124	  if (leveledUp) msg += ' 🎉升级至Lv.' + sk.level + '!';
125	
126	  return msg;
127	}
128	
129	/** 技能升级时提升关联属性 */
130	function applySkillLevelUpBonus(skillKey, state) {
131	  var p = state.player;
132	  var strengthSkills = ['cooking', 'welding', 'repair', 'electrician'];
133	  var intSkills = ['coding', 'english', 'accounting', 'management'];
134	  var agilitySkills = ['driving', 'sales'];
135	
136	  if (strengthSkills.indexOf(skillKey) !== -1) {
137	    if (p.physique < 100) p.physique = Math.min(100, p.physique + 1);
138	  }
139	  if (intSkills.indexOf(skillKey) !== -1) {
140	    if (p.intelligence < 100) p.intelligence = Math.min(100, p.intelligence + 1);
141	  }
142	  if (agilitySkills.indexOf(skillKey) !== -1) {
143	    if (p.agility < 100) p.agility = Math.min(100, p.agility + 1);
144	  }
145	}
146	
147	/** 行动后分发微量属性增长 */
148	function grantActionStatGain(actionId, state) {
149	  var statMap = {
