actions.push({
  id: "eat",
  name: "吃顿饭",
  desc: "花15元在路边摊吃个快餐，填饱肚子。",
  icon: "🍚",
  apCost: 10,
  costEstimate: 15,
  disabled: state.resources.cash < 15 ? true : false,
  handler: () => {
    const st = StateManager.getState();
    // 新手上路：前10天吃饭半价
    const isNewbie = st.player.day <= 10;
    const foodCost = isNewbie ? 8 : 15;
    if (st.resources.cash < foodCost) {
      StateManager.addMessage("⚠️ 钱不够吃饭了！", "danger");
      return;
    }
    st.resources.cash -= foodCost;
    st.needs.hunger = Math.min(100, st.needs.hunger + 35);
    st.needs.happiness = Math.min(
      100,
      st.needs.happiness + (isNewbie ? 12 : 8),
    );
    StateManager.addMessage(
      isNewbie
        ? "🍚 你花8元吃了顿饭（新人优惠），肚子饱了心情大好。"
        : "🍚 你花15元吃了顿饭，肚子饱了心情好了。",
      "success",
    );
    consumeAP(10);
  },
});

actions.push({
  id: "shower",
  name: "洗澡",
  desc: "花8元去公共澡堂洗个澡。",
  apCost: 10,
  icon: "🚿",
  costEstimate: 8,
  disabled: state.resources.cash < 8 ? true : false,
  handler: () => {
    const st = StateManager.getState();
    if (st.resources.cash < 8) {
      StateManager.addMessage("⚠️ 不够钱洗澡。", "danger");
      return;
    }
    st.resources.cash -= 8;
    st.needs.hygiene = Math.min(100, st.needs.hygiene + 40);
    StateManager.addMessage("🚿 洗了个澡，神清气爽。", "success");
    consumeAP(10);
  },
});

// 银行相关行动
if (locKey === "bank") {
  actions.push({
    id: "deposit",
    name: "存款",
    desc: "把钱存入银行，吃利息也更安全。",
    icon: "🏦",
    disabled: state.resources.cash <= 0 ? true : false,
    handler: () => {
      showDepositModal();
    },
  });
  actions.push({
    id: "withdraw",
    name: "取款",
    desc: "从银行取出存款。",
    icon: "💰",
    disabled: state.resources.bankBalance <= 0 ? true : false,
    handler: () => {
      showWithdrawModal();
    },
  });
  actions.push({
    id: "loan",
    name: "贷款",
    desc: "向银行贷款（日息0.3%），解燃眉之急。",
    icon: "📝",
    handler: () => {
      showLoanModal();
    },
  });
  actions.push({
    id: "repay",
    name: "🏦 还银行贷款",
    desc: "偿还银行贷款。",
    icon: "💸",
    disabled:
      (state.resources.bankDebt || 0) <= 0 && state.resources.cash <= 0
        ? true
        : false,

