/**
 * 技能→系统加成映射 — 技能影响多系统（吃饭/旅行/工作/银行/职场等）
 *
 * 设计理念：每项技能不仅解锁工作，还对相关的游戏系统产生渐进式加成，
 * 让技能培养有持续正反馈，形成"学以致用"的良性循环。
 */

/** cooking技能 → 自己做饭折扣（技能越高做饭越划算） */
function getCookingDiscount(cookingLevel) {
  // 自己做饭花费 = 基础花费 * (1 - cookingLevel * 0.008)
  // level 0: 全额, level 50: 6折, level 100: 2折（最低保底3折）
  return Math.min(0.7, cookingLevel * 0.008);
}

/** driving技能 → 旅行AP减免 */
function getTravelApReduction(drivingLevel) {
  // 每20级减1AP，最多减5AP
  return Math.min(5, Math.floor(drivingLevel / 20));
}

/** english技能 → 家教额外收入加成 */
function getTutoringBonus(englishLevel) {
  return englishLevel * 0.3;
}

/** accounting技能 → 银行利率加成 */
function getBankRateBonus(accountingLevel) {
  // 每年最多+5%（日息约+0.00014），100级满分
  return accountingLevel * 0.0005;
}

/** electrician技能 → 工厂类工作收入加成百分比 */
function getFactoryBonus(electricianLevel) {
  return electricianLevel * 0.005;
}

/** welding技能 → 建筑类工作收入加成百分比 */
function getConstructionBonus(weldingLevel) {
  return weldingLevel * 0.008;
}

/** coding技能 → 职场能力加成（每10级+2点ability） */
function getCorpAbilityBonus(codingLevel) {
  return Math.floor(codingLevel / 10) * 2;
}

/** management技能 → 职场向上管理加成（每10级+1点upwardMgmt） */
function getCorpUpwardBonus(managementLevel) {
  return Math.floor(managementLevel / 10) * 1;
}

/** repair技能 → 装备/工具效果加成（百分比） */
function getRepairBonus(repairLevel) {
  return repairLevel * 0.005;
}

/** sales技能 → 交易买卖价格优势 */
function getSalesTradeDiscount(salesLevel) {
  // 买入折扣：最高15%
  return Math.min(0.15, salesLevel * 0.002);
}
function getSalesTradePremium(salesLevel) {
  // 卖出溢价：最高15%
  return Math.min(0.15, salesLevel * 0.002);
}

/**
 * 工作后分发技能经验值（与工作类型关联）
 * 返回字符串描述获得了什么XP
 */
function grantJobSkillXp(jobId, state) {
  var job = typeof STREET_JOBS !== 'undefined'
    ? STREET_JOBS.find(function(j) { return j.id === jobId; })
    : null;
  if (!job) return '';

  var xpMap = {
    // 烹饪相关工作 → cooking XP
    street_vending_food: { skill: 'cooking', min: 2, max: 5 },
    food_stall: { skill: 'cooking', min: 3, max: 7 },
    // 销售相关工作 → sales XP
    street_vending_goods: { skill: 'sales', min: 2, max: 5 },
    barber: { skill: 'sales', min: 2, max: 4 },
    // 维修相关工作 → repair XP
    skilled_labor_construction: { skill: 'repair', min: 3, max: 6 },
    repair_service: { skill: 'repair', min: 4, max: 8 },
    // 英语相关工作 → english XP
    tutoring: { skill: 'english', min: 2, max: 4 },
    // 驾驶相关工作 → driving XP
    delivery_rider: { skill: 'driving', min: 3, max: 6 },
    // 电工相关工作 → electrician XP
    factory_work_assembly: { skill: 'electrician', min: 2, max: 4 },
    factory_overtime: { skill: 'electrician', min: 3, max: 6 },
    // 焊接相关工作 → welding XP
    manual_labor_construction: { skill: 'welding', min: 1, max: 3 },
  };

  var entry = xpMap[jobId];
  if (!entry) return '';

  var sk = state.skills[entry.skill];
  if (!sk) return '';

  var xpGain = entry.min + Math.floor(Math.random() * (entry.max - entry.min + 1));

  // 情绪加成技能XP（happy时1.5倍，depressed时0.3倍）
  var emoMod = typeof getEmotionWorkModifier === 'function'
    ? getEmotionWorkModifier(state)
    : { skillXp: 1.0 };
  xpGain = Math.round(xpGain * emoMod.skillXp);

  // 智力高有一定加成
  var intBonus = Math.floor((state.player.intelligence || 0) / 30);
  xpGain += intBonus;

  sk.xp = (sk.xp || 0) + xpGain;

  // 检查升级
  var leveledUp = false;
  while (sk.xp >= (sk.level + 1) * 120 && sk.level < 100) {
    sk.xp -= (sk.level + 1) * 120;
    sk.level++;
    leveledUp = true;
    // 升级提升关联属性（微量）
    applySkillLevelUpBonus(entry.skill, state);
  }

  var msg = '📚 ' + getSkillChineseName(entry.skill) + ' +' + xpGain + 'XP';
  if (leveledUp) msg += ' 🎉升级至Lv.' + sk.level + '!';

  return msg;
}

/** 技能升级时提升关联属性 */
function applySkillLevelUpBonus(skillKey, state) {
  var p = state.player;
  var strengthSkills = ['cooking', 'welding', 'repair', 'electrician'];
  var intSkills = ['coding', 'english', 'accounting', 'management'];
  var agilitySkills = ['driving', 'sales'];

  if (strengthSkills.indexOf(skillKey) !== -1) {
    if (p.physique < 100) p.physique = Math.min(100, p.physique + 1);
  }
  if (intSkills.indexOf(skillKey) !== -1) {
    if (p.intelligence < 100) p.intelligence = Math.min(100, p.intelligence + 1);
  }
  if (agilitySkills.indexOf(skillKey) !== -1) {
    if (p.agility < 100) p.agility = Math.min(100, p.agility + 1);
  }
}

/** 行动后分发微量属性增长 */
function grantActionStatGain(actionId, state) {
  var statMap = {
    scavenge_trash: { physique: 0.1 },
    manual_labor_construction: { physique: 0.2 },
    factory_work_assembly: { agility: 0.2 },
    factory_overtime: { physique: 0.1, agility: 0.1 },
    barber: { agility: 0.1 },
    delivery_rider: { agility: 0.2 },
    street_performer: { mental: 0.1, fame: 1 },
    busking: { mental: 0.1, fame: 0.5 },
    tutoring: { intelligence: 0.1 },
    gym: { physique: 0.5 + Math.random() * 0.5 },
    night_school: { intelligence: 0.2 },
    meditation: { mental: 0.3 },
    diary: { mental: 0.1 },
    skilled_labor_construction: { physique: 0.1 },
  };

  var entry = statMap[actionId];
  if (!entry) return '';

  var p = state.player;
  var gains = [];

  Object.keys(entry).forEach(function(key) {
    var gain = entry[key];
    if (key === 'fame') {
      state.status.fame = (state.status.fame || 0) + gain;
    } else if (p[key] !== undefined && p[key] < 100) {
      p[key] = Math.min(100, p[key] + gain);
    }
    if (gain >= 0.5) {
      gains.push(getStatChineseName(key) + ' +' + gain.toFixed(1));
    }
  });

  return gains.length > 0 ? '💪 ' + gains.join(', ') : '';
}

/** 获取技能中文名 */
function getSkillChineseName(skillKey) {
  var names = {
    cooking: '烹饪', repair: '维修', coding: '编程', english: '英语',
    driving: '驾驶', sales: '销售', management: '管理', accounting: '会计',
    electrician: '电工', welding: '焊接',
  };
  return names[skillKey] || skillKey;
}

/** 获取属性中文名 */
function getStatChineseName(key) {
  var names = {
    physique: '体质', intelligence: '智力', agility: '敏捷', mental: '心智',
    health: '健康', hunger: '饱食度', fatigue: '疲劳', hygiene: '卫生',
    happiness: '心情', fame: '名气',
  };
  return names[key] || key;
}

/**
 * 街头工作定义（15+种）
 *
 * 每项工作格式:
 * {
 *   id, name, desc, icon,                    // 显示
 *   location: '...',                          // 需要在此地点
 *   requirements: { ... },                    // 属性/技能/年龄要求
 *   effects: { ... },                         // 执行后属性变化
 *   payCalc(state),                           // 收入计算函数（引用 state）
 *   risk: { injury, illness },                // 风险概率
 *   startupCost: 0,                           // 启动资金（可选）
 * }
 */

const STREET_JOBS = [
  // ====== 城中村 ======
  {
    id: "waste_recycling",
    name: "废品回收",
    desc: "走街串巷收废纸板、废金属、废塑料，转手卖给回收站。脏活累活但门槛最低。",
    icon: "♻️",
    location: "slum",
    requirements: { minAge: 16, maxAge: 65 },
    effects: {
      fatigue: 22,
      hygiene: -15,
      happiness: -5,
      physiqueXp: 2,
      agilityXp: 1,
    },
    payCalc(state) {
      const base = 20 + Math.random() * 35;
      const multi = 1 + state.skills.sales.level * 0.005;
      return Math.floor(base * Math.min(multi, 2));
    },
    risk: { injury: 0.04, illness: 0.03 },
  },

  // ====== 商业区 — 摆摊 ======
  {
    id: "street_vending_food",
    name: "摆摊卖小吃",
    desc: "在街边支个小摊卖烤串、煎饼果子。手艺越好，回头客越多。",
    icon: "🍢",
    location: "commercialDist",
    requirements: { minAge: 16, maxAge: 60 },
    effects: { fatigue: 16, hygiene: -5, happiness: 3, cookingXp: 4 },
    payCalc(state) {
      const skillBonus = state.skills.cooking.level * 0.8;
      return Math.floor(45 + skillBonus + Math.random() * 35);
    },
    startupCost: 50,
    risk: {},
  },
  {
    id: "street_vending_goods",
    name: "摆摊卖小商品",
    desc: "从批发市场进些日用品、小电子产品，在商业区摆摊赚差价。",
    icon: "🧦",
    location: "commercialDist",
    requirements: { minAge: 16, maxAge: 60 },
    effects: { fatigue: 14, happiness: 2, salesXp: 3 },
    payCalc(state) {
      const skillBonus = state.skills.sales.level * 0.6;
      return Math.floor(38 + skillBonus + Math.random() * 28);
    },
    startupCost: 30,
    risk: { injury: 0.02 },
  },

  // ====== 建筑工地 ======
  {
    id: "manual_labor_construction",
    name: "建筑工地苦力",
    desc: "在工地搬砖、扛水泥、推砂石。纯体力活，工资日结不拖欠。",
    icon: "🧱",
    location: "construction",
    requirements: { physique: 20, minAge: 18, maxAge: 55 },
    effects: { fatigue: 38, hygiene: -22, physiqueXp: 6, happiness: -10 },
    payCalc(state) {
      const weldBonus = typeof getConstructionBonus === 'function'
        ? getConstructionBonus(state.skills.welding.level || 0) : 0;
      return Math.floor((65 + state.player.physique * 0.5 + Math.random() * 30) * (1 + weldBonus));
    },
    risk: { injury: 0.1, illness: 0.04 },
  },
  {
    id: "skilled_labor_construction",
    name: "工地技术工",
    desc: "会手艺的工地活——水电安装、木工、钢筋工。收入比苦力高不少。",
    icon: "🔨",
    location: "construction",
    requirements: {
      physique: 25,
      repair: 15,
      agility: 20,
      minAge: 20,
      maxAge: 60,
    },
    effects: { fatigue: 28, hygiene: -12, physiqueXp: 3, repairXp: 5, weldingXp: 2 },
    payCalc(state) {
      const weldBonus = typeof getConstructionBonus === 'function'
        ? getConstructionBonus(state.skills.welding.level || 0) : 0;
      return Math.floor(
        (120 + state.skills.repair.level * 1.2 + state.player.physique * 0.25 + Math.random() * 35)
        * (1 + weldBonus)
      );
    },
    risk: { injury: 0.05 },
  },

  // ====== 工业区 — 工厂 ======
  {
    id: "factory_work_assembly",
    name: "工厂流水线",
    desc: "在电子厂做装配工。机械重复手不停，但收入稳定包吃住。",
    icon: "🏭",
    location: "factoryZone",
    requirements: { agility: 15, minAge: 18, maxAge: 45 },
    effects: {
      fatigue: 28,
      hygiene: -5,
      happiness: -15,
      mental: -2,
      agilityXp: 3,
      electricianXp: 2,
    },
    payCalc(state) {
      const elecBonus = typeof getFactoryBonus === 'function'
        ? getFactoryBonus(state.skills.electrician.level || 0) : 0;
      return Math.floor((80 + state.player.agility * 0.3 + Math.random() * 18) * (1 + elecBonus));
    },
    risk: { injury: 0.03, illness: 0.02 },
  },
  {
    id: "factory_overtime",
    name: "工厂加班",
    desc: "晚上加班赶订单，加班费可观，但这钱是用身体换的。",
    icon: "🌙",
    location: "factoryZone",
    requirements: { agility: 15, physique: 18, minAge: 18, maxAge: 45 },
    effects: { fatigue: 42, hygiene: -3, happiness: -20, mental: -4, electricianXp: 3 },
    payCalc(state) {
      const elecBonus = typeof getFactoryBonus === 'function'
        ? getFactoryBonus(state.skills.electrician.level || 0) : 0;
      return Math.floor((115 + state.player.physique * 0.4 + Math.random() * 25) * (1 + elecBonus));
    },
    risk: { illness: 0.06 },
  },

  // ====== 商业区 — 餐饮服务 ======
  {
    id: "food_stall",
    name: "餐饮摊贩",
    desc: "租个小摊位卖早餐、夜宵。辛苦但利润不错，手艺好能赚更多。",
    icon: "🍜",
    location: "commercialDist",
    requirements: { cooking: 10, minAge: 18, maxAge: 55 },
    effects: { fatigue: 22, hygiene: -8, cookingXp: 5, happiness: 2 },
