1	/**
2	 * 每日结算管线 — 声明式步骤编排
3	 *
4	 * 将 endDay 的 14 步硬编码拆为独立管线步骤，每步自声明：
5	 *   name: 唯一标识
6	 *   fn: 执行函数
7	 *   after: 依赖的前置步骤（可选）
8	 *   skipOnExtreme: 极端状态时是否跳过（默认 true）
9	 *
10	 * 架构原则：新增结算逻辑只需向 DAILY_PIPELINE 数组添加一个步骤对象，
11	 * 不需要修改 endDay 的主流程。
12	 *
13	 * MiniMax 友好：每个步骤的输入输出清晰，依赖声明显式化。
14	 */
15	
16	/** 每日结算步骤管线（按顺序执行） */
17	const DAILY_PIPELINE = [
18	  // === 基础递进 ===
19	  { name: 'day_increment', fn: function(state) {
20	    state.player.day++;
21	    state.player.actionPoints = state.player.maxActionPoints;
22	    state.player.timeSlot = 'morning';
23	  }},
24	
25	  // === 需求衰减 ===
26	  { name: 'needs_decay', fn: function(state) {
27	    applyNeedsDecay(state);
28	  }},
29	
30	  // === 状态交叉影响 ===
31	  { name: 'status_interactions', fn: function(state) {
32	    applyStatusInteractions(state);
33	  }},
34	
35	  // === 睡眠恢复 ===
36	  { name: 'sleep_recovery', fn: function(state) {
37	    var house = getCurrentHousing(state);
38	    var recovery = house.fatigueRecovery;
39	    var penalty = state._fatigueRecoveryPenalty || 1.0;
40	    if (penalty < 1.0) {
41	      StateManager.addMessage('😢 心情低落，睡眠质量很差，疲劳恢复减半。', 'warning');
42	    }
43	    state.needs.fatigue = Math.max(0, state.needs.fatigue - Math.round(recovery * penalty));
44	    delete state._fatigueRecoveryPenalty;
45	    state.needs.hygiene = Math.min(100, state.needs.hygiene + (house.hygieneBonus || 0));
46	    state.needs.happiness = Math.max(0, Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)));
47	  }},
48	
49	  // === 房租 ===
50	  { name: 'rent', fn: function(state) {
51	    var house = getCurrentHousing(state);
52	    if (house.rent > 0) {
53	      if (state.resources.cash >= house.rent) {
54	        state.resources.cash -= house.rent;
55	      } else {
56	        StateManager.addMessage('⚠️ 付不起房租 ¥' + house.rent + '！被赶回流落街头。', 'danger');
57	        state.housing.tier = 0;
58	        state.inventory.capacity = 20 + (state.housing ? state.housing.storageCapacity || 0 : 0);
59	      }
60	    }
61	    if (state.housing && state.housing.storageRented && state.housing.storageCapacity > 0) {
62	      var storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
63	      if (state.resources.cash >= storageRent) {
64	        state.resources.cash -= storageRent;
65	      } else {
66	        StateManager.addMessage('⚠️ 付不起仓库租金，仓库被收回。', 'danger');
67	        state.housing.storageRented = false;
68	        state.housing.storageCapacity = 0;
69	        var baseCap = [20, 50, 100, 200][state.housing.tier || 0];
70	        state.inventory.capacity = baseCap;
71	      }
72	    }
73	  }},
74	
75	  // === 健康结算 ===
76	  { name: 'health_tick', fn: function(state) {
77	    tickHealthStatus(state);
78	  }},
79	
80	  // === 需求阈值检查 ===
81	  { name: 'needs_check', fn: function(state) {
82	    checkNeedsThresholds(state);
83	  }},
84	
85	  // === 极端状态检测 ===
86	  { name: 'extreme_check', fn: function(state) {
87	    var result = checkExtremeConditions(state);
88	    // 返回 null=正常, 'skip_day' 由调用方处理
89	    return result;
90	  }},
91	
92	  // === 情绪判定 ===
93	  { name: 'emotion', fn: function(state) {
94	    determineEmotionalState(state);
95	  }},
96	
97	  // === 财务结算 ===
98	  { name: 'finance', fn: function(state) {
99	    settleDailyFinance(state);
100	  }},
101	
102	  // === 价格更新 ===
103	  { name: 'price_update', fn: function(state) {
104	    if (state.player.day - state.trade.lastPriceUpdate >= 3) {
105	      updateAllPrices(state);
106	    }
107	  }},
108	
109	  // === 投资tick ===
110	  { name: 'investment_tick', fn: function(state) {
111	    tickInvestmentDaily(state);
112	  }},
113	
114	  // === 天气 ===
115	  { name: 'weather', fn: function(state) {
116	    rollWeather(state);
117	  }},
118	
119	  // === 新闻 ===
120	  { name: 'news', fn: function(state) {
121	    rollDailyNews(state);
122	  }},
123	
124	  // === 城管热度衰减 ===
125	  { name: 'chengguan_decay', fn: function(state) {
126	    if (state.chengguan) {
127	      state.chengguan.heat = Math.max(0, state.chengguan.heat - 5 - Math.floor(Math.random() * 5));
128	    }
129	  }},
130	
131	  // === 清理 ===
132	  { name: 'cleanup', fn: function(state) {
133	    dailyCleanup(state);
134	  }},
135	
136	  // === 年龄增长 ===
137	  { name: 'age', fn: function(state) {
138	    if (state.player.day % 365 === 0) {
139	      state.player.age++;
140	      StateManager.addMessage('🎂 又过了一年，你现在' + state.player.age + '岁了。', 'event');
141	    }
142	  }},
143	
144	  // === 训练次数重置 ===
145	  { name: 'reset_training', fn: function(state) {
146	    if (state.flags._dailyTrainingCounts) {
147	      state.flags._dailyTrainingCounts = {};
148	    }
149	  }},
150	
151	  // === 胜利判定 ===
152	  { name: 'victory', fn: function(state) {
153	    checkVictoryPaths(state);
154	  }},
155	
156	  // === 失败判定 ===
157	  { name: 'lose', fn: function(state) {
158	    checkLoseConditions(state);
159	  }},
160	
161	  // === 自动存档 ===
162	  { name: 'autosave', fn: function(state) {
163	    autoSave();
164	  }},
165	
166	  // === 结束日志 ===
167	  { name: 'end_log', fn: function(state) {
168	    var emoIcon = getEmotionIcon(state);
169	    StateManager.addMessage('🌙 第' + state.player.day + '天结束。' + emoIcon + ' 新的一天开始了。', 'info');
170	  }}
171	];
172	
173	/**
174	 * 执行每日结算管线。
175	 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
176	 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
177	 */
178	function runDailyPipeline(state) {
179	  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
180	    var step = DAILY_PIPELINE[i];
181	
182	    // 极端状态短路逻辑：
183	    // extreme_check 步骤返回 'skip_day' 时，跳过后续非核心步骤
184	    // 但 finance / autosave 始终执行（保证利息和存档不丢）
185	    if (step.name === 'extreme_check') {
186	      var result = step.fn(state);
187	      if (result === 'skip_day') {
188	        StateManager.addMessage('🌙 第' + state.player.day + '天在昏迷中过去了...', 'danger');
189	        // 执行最后的核心步骤：财务、存档
190	        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
191	          var lateStep = DAILY_PIPELINE[j];
192	          if (lateStep.name === 'finance' || lateStep.name === 'autosave') {
193	            lateStep.fn(state);
194	          }
195	        }
196	        return; // 短路
197	      }
198	    } else {
199	      step.fn(state);
200	    }
201	  }
202	}
203	
204	/**
205	 * endDay — 仅保留管线调度逻辑（MiniMax 友好：170行→8行）
206	 */
207	function endDay() {
208	  var state = StateManager.getState();
209	  runDailyPipeline(state);
210	}

