/** 送礼模态框 */
function showGiftModal() {
  var state = StateManager.getState();
  var currentLoc = state.trade.currentLocation;
  var npcsHere = typeof getNpcsAtLocation === 'function' ? getNpcsAtLocation(currentLoc) : [];
  if (npcsHere.length === 0) {
    StateManager.addMessage('🎁 这里没有熟悉的人可以送礼。', 'warning');
    return;
  }
  var goodsIds = typeof GOODS !== 'undefined' ? GOODS.map(function(g) { return g.id; }) : [];
  var invGoods = (state.inventory.items || []).filter(function(item) {
    return goodsIds.includes(item.id) && item.qty > 0;
  });
  if (invGoods.length === 0) {
    StateManager.addMessage('🎁 背包里没有可以送人的商品。去批发市场买些小礼品吧。', 'warning');
    return;
  }
  var npcOptions = npcsHere.map(function(npc) {
    var rel = state.relationships[npc.id] || { affinity: 0 };
    var label = typeof getAffinityLabel === 'function' ? getAffinityLabel(rel.affinity) : '';
    return '<option value="' + npc.id + '">' + npc.name + '（' + npc.role + '）' + label + '</option>';
  }).join('');
  var goodOptions = invGoods.map(function(item) {
    var goodDef = typeof GOODS !== 'undefined' ? GOODS.find(function(g) { return g.id === item.id; }) : null;
    var name = goodDef ? goodDef.name : item.id;
    return '<option value="' + item.id + '">' + name + ' ×' + item.qty + '</option>';
  }).join('');
  showModal({
    title: '🎁 送礼联络感情',
    body: '<p style="font-size:12px;color:var(--text-secondary);">投其所好+15好感，普通礼物+5好感，每天每人限送一次。</p>' +
      '<label style="display:block;margin-top:10px;">选择对象：' +
      '<select id="gift-npc" style="width:100%;padding:8px;margin-top:4px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;">' +
      npcOptions + '</select></label>' +
      '<label style="display:block;margin-top:10px;">送出商品：' +
      '<select id="gift-good" style="width:100%;padding:8px;margin-top:4px;background:var(--bg-input);border:1px solid var(--border);color:var(--text-primary);border-radius:4px;">' +
      goodOptions + '</select></label>',
    buttons: [
      { text: '取消', cls: '', callback: function() {} },
      {
        text: '送出 (-10AP)', cls: 'btn-primary',
        callback: function() {
          var st = StateManager.getState();
          var npcId = document.getElementById('gift-npc') ? document.getElementById('gift-npc').value : '';
          var goodId = document.getElementById('gift-good') ? document.getElementById('gift-good').value : '';
          if (!npcId || !goodId) return;
          var npc = typeof getNpcById === 'function' ? getNpcById(npcId) : null;
          if (!npc) return;
          // Daily limit check
          var todayKey = '_giftToday_' + npcId;
          if (st.flags[todayKey] === st.player.day) {
            StateManager.addMessage('🎁 今天已经给' + npc.name + '送过礼了。', 'warning');
            document.querySelector('.modal-overlay') && document.querySelector('.modal-overlay').remove();
            return;
          }
          // Remove good from inventory
          var invItem = (st.inventory.items || []).find(function(i) { return i.id === goodId; });
          if (!invItem || invItem.qty <= 0) {
            StateManager.addMessage('🎁 商品数量不足。', 'warning');
            return;
          }
          invItem.qty--;
          if (invItem.qty <= 0) {
            st.inventory.items = st.inventory.items.filter(function(i) { return i.id !== goodId; });
          }
          // Grant affinity
          if (!st.relationships[npcId]) st.relationships[npcId] = { affinity: 0, met: true };
          var rel = st.relationships[npcId];
          var isPreferred = npc.giftPrefers && npc.giftPrefers.includes(goodId);
          var bonus = isPreferred ? 15 : 5;
          rel.affinity = Math.min(100, rel.affinity + bonus);
          rel.met = true;
          st.flags[todayKey] = st.player.day;
          var goodDef = typeof GOODS !== 'undefined' ? GOODS.find(function(g) { return g.id === goodId; }) : null;
          var goodName = goodDef ? goodDef.name : goodId;
          if (isPreferred) {
            StateManager.addMessage('🎁 ' + npc.name + '眼睛一亮："正合我意！" 好感度+15。（当前：' + rel.affinity + '）', 'success');
          } else {
            StateManager.addMessage('🎁 给' + npc.name + '送了' + goodName + '，对方礼貌收下。好感度+5。（当前：' + rel.affinity + '）', 'info');
          }
          consumeAP(10);
          document.querySelector('.modal-overlay') && document.querySelector('.modal-overlay').remove();
          if (typeof renderAll === 'function') renderAll();
        }
      }
    ]
  });
}

