    desc: '在这座城市生存了30天。',
    story: '第一个月是最难的。但你撑过来了。',
    icon: '📅',
    category: '里程碑',
    hidden: false,
    check: function(st) { return (st.player.day || 0) >= 30; },
  },
  {
    id: 'survive_100_days',
    name: '百日漂泊',
    desc: '在这座城市生存了100天。',
    story: '一百个日出日落，一百次晚上数着口袋里的钱。这座城市还没把你打倒。',
    icon: '📅',
    category: '里程碑',
    hidden: false,
    check: function(st) { return (st.player.day || 0) >= 100; },
  },
  {
    id: 'repay_debt',
    name: '还清欠债',
    desc: '你还清了所有欠下的钱。',
    story: '那压着你的石头终于搬开了。那一刻，你深深地呼了口气。',
    icon: '🎉',
    category: '里程碑',
    hidden: false,
    check: function(st) { return (st.resources.villageDebt || 0) <= 0 && (st.resources.bankDebt || 0) <= 0; },
  },
  {
    id: 'enter_corporate',
    name: '白领元年',
    desc: '你进入了职场，开始了人生的新篇章。',
    story: '西装或许还不合身，但工牌上有你的名字。你不再是街头小贩了。',
    icon: '🏢',
    category: '里程碑',
    hidden: false,
    check: function(st) { return st.player.phase === 'corporate'; },
  },
  {
    id: 'reach_p8',
    name: 'P8精英',
    desc: '在职场晋升到P8。',
    story: '同届进来的一半人都走了，你还在，而且往上走了。',
    icon: '🚀',
    category: '里程碑',
    hidden: false,
    check: function(st) {
      var rank = st.corporate && st.corporate.rank;
      return rank === 'P8' || rank === 'P9' || rank === 'P10';
    },
  },
  {
    id: 'all_skills_10',
    name: '全能打工人',
    desc: '所有技能都达到10级。',
    story: '电工、厨师、驾驶、销售……你什么都会一点，这座城市找不到你干不了的活。',
    icon: '🌟',
    category: '里程碑',
    hidden: false,
    check: function(st) {
      return Object.values(st.skills).every(function(s) { return s.level >= 10; });
    },
  },

  // === 道德档案（隐藏，记录重大道德选择）===
  {
    id: 'moral_kept_wallet',
    name: '拾金不昧',
    desc: '你捡到钱包后选择上交。这件事没人知道，但你知道。',
    story: '那天你可以拿走那些钱，但你没有。有些事，记在良心账本里。',
    icon: '👛',
    category: '道德档案',
    hidden: true,
    check: function(st) { return st.flags && st.flags._keptWallet; },
  },
  {
    id: 'moral_helped_coworker',
    name: '工友的守护者',
    desc: '你在工头压力下仍然为受伤工友叫了救护车。',
    story: '那天你可以拿200块走开，但你选择了打120。失去了工头的好感，但留下了良心。',
    icon: '🚑',
    category: '道德档案',
    hidden: true,
    check: function(st) { return st.flags && st.flags._helpedCoworker; },
  },
  {
    id: 'moral_refused_fake',
    name: '诚信商人',
    desc: '你宁可认赔¥800，也不把假货卖给顾客。',
    story: '那批货扔掉的时候，你觉得亏了。但你在这座城市的名字，慢慢变得值钱了。',
    icon: '🗑️',
    category: '道德档案',
    hidden: true,
    check: function(st) { return st.flags && st.flags._refusedFakeGoods; },
  },
  {
    id: 'moral_fought_wage_theft',
    name: '维权先锋',
    desc: '你去劳动局追回了被拖欠的工资。',
    story: '那段路走得不容易，但你为自己争了权益，也为那些没勇气去的人树了个榜样。',
    icon: '🏛️',
    category: '道德档案',
    hidden: true,
    check: function(st) { return st.flags && st.flags._foughtWageTheft; },
  },

  // === 隐藏成就 ===
  {
    id: 'hidden_broke',
    name: '穷到骨子里',
    desc: '你的现金曾经归零。',
    story: '那一刻，口袋里一分不剩。你记住了这种感觉，然后爬起来了。',
    icon: '💸',
    category: '隐藏',
    hidden: true,
    check: function(st) { return st.flags && st.flags._everBroke; },
  },
  {
    id: 'hidden_starved',
    name: '饿过',
    desc: '你经历过饥饿值归零的时刻。',
    story: '肚子贴着背的感觉，你这辈子不会忘。',
    icon: '🍞',
    category: '隐藏',
    hidden: true,
    check: function(st) { return st.flags && st.flags._everStarved; },
  },
  {
    id: 'hidden_friend_all_npc',
    name: '人缘极好',
    desc: '你和每一个认识的NPC好感度都达到了60+。',
    story: '每个人都记得你，每个人都愿意帮你。人脉，是另一种形式的财富。',
    icon: '🤝',
    category: '隐藏',
    hidden: true,
    check: function(st) {
      if (!st.relationships) return false;
      var npcIds = ['aunt_wang','boss_li','sister_zhang','old_zhou','xiao_mei','chef_chen'];
      return npcIds.every(function(id) {
        return st.relationships[id] && st.relationships[id].affinity >= 60;
      });
    },
  },
  {
    id: 'hidden_no_beg',
    name: '从不低头',
    desc: '生存了100天，从未乞讨过。',
    story: '有些钱，弯腰低头才能捡到，你没有弯。不是因为你不缺，是因为你选择了别的方式。',
    icon: '💪',
    category: '隐藏',
    hidden: true,
    check: function(st) { return st.player.day >= 100 && !(st.flags && st.flags._everBegged); },
  },
];

/**
 * 检查并解锁新成就，返回本次新解锁的成就列表
 */
function checkAchievements(state) {
  if (!state.flags._unlockedAchievements) state.flags._unlockedAchievements = [];
  var unlocked = state.flags._unlockedAchievements;
  var newlyUnlocked = [];
  ACHIEVEMENTS.forEach(function(ach) {
    if (unlocked.indexOf(ach.id) !== -1) return; // 已解锁
    try {
      if (ach.check(state)) {
        unlocked.push(ach.id);
        newlyUnlocked.push(ach);
      }
    } catch(e) {}
  });
  return newlyUnlocked;
}

/**
 * 在每日结算和关键行动后调用，展示新解锁成就
 */
function notifyNewAchievements(state) {
  var newOnes = checkAchievements(state);
  newOnes.forEach(function(ach) {
    StateManager.addMessage(
      '🏅 成就解锁：【' + ach.name + '】 — ' + ach.story,
      'event'
    );
  });
  return newOnes.length;
}

/** 获取全部成就（含解锁状态） */
function getAchievementsWithStatus(state) {
  var unlocked = (state.flags && state.flags._unlockedAchievements) || [];
  return ACHIEVEMENTS.map(function(ach) {
    var isUnlocked = unlocked.indexOf(ach.id) !== -1;
    return {
      id: ach.id,
      name: isUnlocked || !ach.hidden ? ach.name : '???',
      desc: isUnlocked || !ach.hidden ? ach.desc : '达成特定条件解锁',
      story: isUnlocked ? ach.story : null,
      icon: isUnlocked || !ach.hidden ? ach.icon : '🔒',
      category: ach.category,
      hidden: ach.hidden,
      unlocked: isUnlocked,
    };
  });
}

