// ====== Achievements Tab ======
function renderAchievementsTab(state, parent) {
  parent.innerHTML = '';
  if (typeof getAchievementsWithStatus !== 'function') {
    parent.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:40px;">🏅 成就系统加载中...</p>';
    return;
  }
  var all = getAchievementsWithStatus(state);
  var unlockedCount = all.filter(function(a) { return a.unlocked; }).length;
  var totalVisible = all.filter(function(a) { return !a.hidden || a.unlocked; }).length;

  var header = document.createElement('div');
  header.style.cssText = 'padding:12px 16px;background:var(--bg-card);border-bottom:1px solid var(--border);margin-bottom:8px;';
  header.innerHTML = '<h3 style="margin:0;font-size:14px;color:var(--text-primary);">🏅 成就档案</h3>' +
    '<p style="margin:4px 0 0;font-size:11px;color:var(--text-muted);">已解锁 ' + unlockedCount + ' / ' + totalVisible + ' 个 &nbsp;|&nbsp; 记录你在这座城市走过的路</p>';
  parent.appendChild(header);

  var categories = ['人生第一次', '里程碑', '道德档案', '隐藏'];
  categories.forEach(function(cat) {
    var catAchs = all.filter(function(a) { return a.category === cat && (!a.hidden || a.unlocked); });
    if (catAchs.length === 0) return;
    var section = document.createElement('div');
    section.style.cssText = 'margin-bottom:12px;';
    var catTitle = document.createElement('div');
    catTitle.style.cssText = 'padding:6px 16px;font-size:11px;font-weight:bold;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.5px;';
    catTitle.textContent = cat;
    section.appendChild(catTitle);
    catAchs.forEach(function(ach) {
      var card = document.createElement('div');
      card.style.cssText = 'display:flex;gap:10px;align-items:flex-start;padding:10px 14px;margin:2px 8px;background:var(--bg-card);border:1px solid ' +
        (ach.unlocked ? 'var(--accent)' : 'var(--border)') + ';border-radius:8px;opacity:' + (ach.unlocked ? '1' : '0.55') + ';';
      var iconEl = document.createElement('div');
      iconEl.style.cssText = 'font-size:22px;flex-shrink:0;';
      iconEl.textContent = ach.icon;
      var info = document.createElement('div');
      info.style.cssText = 'flex:1;min-width:0;';
      var nameEl = document.createElement('div');
      nameEl.style.cssText = 'font-size:13px;font-weight:bold;color:' + (ach.unlocked ? 'var(--text-primary)' : 'var(--text-muted)') + ';';
      nameEl.textContent = ach.name;
      var descEl = document.createElement('div');
      descEl.style.cssText = 'font-size:11px;color:var(--text-secondary);margin-top:2px;';
      descEl.textContent = ach.desc;
      info.appendChild(nameEl);
      info.appendChild(descEl);
      if (ach.unlocked && ach.story) {
        var storyEl = document.createElement('div');
        storyEl.style.cssText = 'font-size:10px;color:var(--text-muted);margin-top:4px;font-style:italic;border-top:1px solid var(--border);padding-top:4px;';
        storyEl.textContent = '"' + ach.story + '"';
        info.appendChild(storyEl);
      }
      card.appendChild(iconEl);
      card.appendChild(info);
      section.appendChild(card);
    });
    parent.appendChild(section);
  });
}
ENDOFFILE
