/**
 * 技能→系统加成映射 — 技能影响多系统（吃饭/旅行/工作/银行/职场等）
 *
 * 设计理念：每项技能不仅解锁工作，还对相关的游戏系统产生渐进式加成，
 * 让技能培养有持续正反馈，形成"学以致用"的良性循环。
 */

/** cooking技能 → 自己做饭折扣（技能越高做饭越划算） */
function getCookingDiscount(cookingLevel) {
  // 自己做饭花费 = 基础花费 * (1 - cookingLevel * 0.008)
  // level 0: 全额, level 50: 6折, level 100: 2折（最低保底3折）
  return Math.min(0.7, cookingLevel * 0.008);
}

/** driving技能 → 旅行AP减免 */
function getTravelApReduction(drivingLevel) {
  // 每20级减1AP，最多减5AP
  return Math.min(5, Math.floor(drivingLevel / 20));
}

/** english技能 → 家教额外收入加成 */
function getTutoringBonus(englishLevel) {
  return englishLevel * 0.3;
}

/** accounting技能 → 银行利率加成 */
function getBankRateBonus(accountingLevel) {
  // 每年最多+5%（日息约+0.00014），100级满分
  return accountingLevel * 0.0005;
}

/** electrician技能 → 工厂类工作收入加成百分比 */
function getFactoryBonus(electricianLevel) {
  return electricianLevel * 0.005;
}

/** welding技能 → 建筑类工作收入加成百分比 */
function getConstructionBonus(weldingLevel) {
  return weldingLevel * 0.008;
}

/** coding技能 → 职场能力加成（每10级+2点ability） */
function getCorpAbilityBonus(codingLevel) {
  return Math.floor(codingLevel / 10) * 2;
}

/** management技能 → 职场向上管理加成（每10级+1点upwardMgmt） */
function getCorpUpwardBonus(managementLevel) {
  return Math.floor(managementLevel / 10) * 1;
}

/** repair技能 → 装备/工具效果加成（百分比） */
function getRepairBonus(repairLevel) {
  return repairLevel * 0.005;
}

/** sales技能 → 交易买卖价格优势 */
function getSalesTradeDiscount(salesLevel) {
  // 买入折扣：最高15%
  return Math.min(0.15, salesLevel * 0.002);
}
function getSalesTradePremium(salesLevel) {
  // 卖出溢价：最高15%
  return Math.min(0.15, salesLevel * 0.002);
}

/**
 * 工作后分发技能经验值（与工作类型关联）
 * 返回字符串描述获得了什么XP
 */
function grantJobSkillXp(jobId, state) {
  var job =
    typeof STREET_JOBS !== "undefined"
      ? STREET_JOBS.find(function (j) {
          return j.id === jobId;
        })
      : null;
  if (!job) return "";

  var xpMap = {
    // 烹饪相关工作 → cooking XP
    street_vending_food: { skill: "cooking", min: 2, max: 5 },
    food_stall: { skill: "cooking", min: 3, max: 7 },
    // 销售相关工作 → sales XP
    street_vending_goods: { skill: "sales", min: 2, max: 5 },
    barber: { skill: "sales", min: 2, max: 4 },
    // 维修相关工作 → repair XP
    skilled_labor_construction: { skill: "repair", min: 3, max: 6 },
    repair_service: { skill: "repair", min: 4, max: 8 },
    // 英语相关工作 → english XP
    tutoring: { skill: "english", min: 2, max: 4 },
    // 驾驶相关工作 → driving XP
    delivery_rider: { skill: "driving", min: 3, max: 6 },
    // 电工相关工作 → electrician XP
    factory_work_assembly: { skill: "electrician", min: 2, max: 4 },
    factory_overtime: { skill: "electrician", min: 3, max: 6 },
    // 焊接相关工作 → welding XP
    manual_labor_construction: { skill: "welding", min: 1, max: 3 },
  };

  var entry = xpMap[jobId];
  if (!entry) return "";

  var sk = state.skills[entry.skill];
  if (!sk) return "";

  var xpGain =
    entry.min + Math.floor(Math.random() * (entry.max - entry.min + 1));

  // 情绪加成技能XP（happy时1.5倍，depressed时0.3倍）
  var emoMod =
    typeof getEmotionWorkModifier === "function"
      ? getEmotionWorkModifier(state)
      : { skillXp: 1.0 };
  xpGain = Math.round(xpGain * emoMod.skillXp);

  // 智力高有一定加成
  var intBonus = Math.floor((state.player.intelligence || 0) / 30);
  xpGain += intBonus;

  sk.xp = (sk.xp || 0) + xpGain;

  // 检查升级
  var leveledUp = false;
  while (sk.xp >= (sk.level + 1) * 120 && sk.level < 100) {
    sk.xp -= (sk.level + 1) * 120;
    sk.level++;
    leveledUp = true;
    // 升级提升关联属性（微量）
    applySkillLevelUpBonus(entry.skill, state);
  }

  var msg = "📚 " + getSkillChineseName(entry.skill) + " +" + xpGain + "XP";
  if (leveledUp) msg += " 🎉升级至Lv." + sk.level + "!";

  return msg;
}

/** 技能升级时提升关联属性 */
function applySkillLevelUpBonus(skillKey, state) {
  var p = state.player;
  var strengthSkills = ["cooking", "welding", "repair", "electrician"];
  var intSkills = ["coding", "english", "accounting", "management"];
  var agilitySkills = ["driving", "sales"];

  if (strengthSkills.indexOf(skillKey) !== -1) {
    if (p.physique < 100) p.physique = Math.min(100, p.physique + 1);
  }
  if (intSkills.indexOf(skillKey) !== -1) {
    if (p.intelligence < 100)
      p.intelligence = Math.min(100, p.intelligence + 1);
  }
  if (agilitySkills.indexOf(skillKey) !== -1) {
    if (p.agility < 100) p.agility = Math.min(100, p.agility + 1);
  }
}

/** 行动后分发微量属性增长 */
function grantActionStatGain(actionId, state) {
  var statMap = {
    scavenge_trash: { physique: 0.1 },
    manual_labor_construction: { physique: 0.2 },
    factory_work_assembly: { agility: 0.2 },
    factory_overtime: { physique: 0.1, agility: 0.1 },
    barber: { agility: 0.1 },
    delivery_rider: { agility: 0.2 },
    street_performer: { mental: 0.1, fame: 1 },
    busking: { mental: 0.1, fame: 0.5 },
    tutoring: { intelligence: 0.1 },
    gym: { physique: 0.5 + Math.random() * 0.5 },
    night_school: { intelligence: 0.2 },
    meditation: { mental: 0.3 },
    diary: { mental: 0.1 },
    skilled_labor_construction: { physique: 0.1 },
  };

  var entry = statMap[actionId];
  if (!entry) return "";

  var p = state.player;
  var gains = [];

  Object.keys(entry).forEach(function (key) {
    var gain = entry[key];
    if (key === "fame") {
      state.status.fame = (state.status.fame || 0) + gain;
    } else if (p[key] !== undefined && p[key] < 100) {
      p[key] = Math.min(100, p[key] + gain);
    }
    if (gain >= 0.5) {
      gains.push(getStatChineseName(key) + " +" + gain.toFixed(1));
    }
  });

  return gains.length > 0 ? "💪 " + gains.join(", ") : "";
}

/** 获取技能中文名 */
function getSkillChineseName(skillKey) {
  var names = {
    cooking: "烹饪",
    repair: "维修",
    coding: "编程",
    english: "英语",
    driving: "驾驶",
    sales: "销售",
    management: "管理",
    accounting: "会计",
    electrician: "电工",
    welding: "焊接",
  };
  return names[skillKey] || skillKey;
}

/**
 * NPC 好感阈值检测 — 每次好感变动后调用
 * 参考 Stardew Valley Heart Events：达到阈值触发一次性奖励
 */
function checkNpcAffinityRewards(npcId, state) {
  var npc = typeof getNpcById === "function" ? getNpcById(npcId) : null;
  if (!npc || !npc.affinityRewards) return;
  var rel = state.relationships[npcId];
  if (!rel) return;
  var affinity = rel.affinity || 0;
  if (!state.flags._npcRewardsClaimed) state.flags._npcRewardsClaimed = {};
  npc.affinityRewards.forEach(function (reward) {
    if (
      affinity >= reward.threshold &&
      !state.flags._npcRewardsClaimed[reward.id]
    ) {
      state.flags._npcRewardsClaimed[reward.id] = true;
      reward.effect(state);
    }
  });
}

/** 每日财务结算 — 银行利息（含accounting技能加成） */
function settleDailyFinance(state) {
  var bal = state.resources.bankBalance || 0;
  if (bal <= 0) return;
  var accountingLvl =
    (state.skills.accounting && state.skills.accounting.level) || 0;
  var baseRate = 0.001;
  var bonus =
    typeof getBankRateBonus === "function"
      ? getBankRateBonus(accountingLvl)
      : 0;
  var rate = baseRate + bonus;
  var interest = Math.floor(bal * rate);
  if (interest > 0) {
    state.resources.bankBalance += interest;
    StateManager.addMessage(
      "🏦 银行利息 +¥" +
        interest +
        "（日利率" +
        (rate * 100).toFixed(3) +
        "%，存款¥" +
        bal.toLocaleString() +
        "）",
      "info",
    );
  }
}

/** 获取属性中文名 */
function getStatChineseName(key) {
  var names = {
    physique: "体质",
    intelligence: "智力",
    agility: "敏捷",
    mental: "心智",
    health: "健康",
    hunger: "饱食度",
    fatigue: "疲劳",
    hygiene: "卫生",
    happiness: "心情",
    fame: "名气",
  };
  return names[key] || key;
}

/**
 * 需求系统 — 饥饱/疲劳/卫生/心情衰减 + 情绪状态判定 + 伤病效果
 */

/** 每日需求衰减 */
function applyNeedsDecay(state) {
  const n = state.needs;
  n.hunger = Math.max(0, n.hunger - 18);
  n.hygiene = Math.max(0, n.hygiene - 8);
  n.happiness = Math.max(0, n.happiness - 3);
  // fatigue 在 endDay 中通过睡眠恢复单独处理
}

/** 检查需求阈值并施加惩罚 */
function checkNeedsThresholds(state) {
  const n = state.needs;
  const msgs = [];

  if (n.hunger < 15) {
    state.status.health = Math.max(0, state.status.health - 5);
    if (n.hunger <= 0) state.flags._everStarved = true; // 成就追踪
    msgs.push("⚠️ 极度饥饿！健康-5。赶紧吃点什么！");
  } else if (n.hunger < 30) {
    state.status.health = Math.max(0, state.status.health - 2);
    msgs.push("🍞 肚子饿了，工作效率下降。");
  }

  if (n.hygiene < 15) {
    state.status.health = Math.max(0, state.status.health - 3);
    msgs.push("🦠 卫生极差！容易生病。去洗个澡吧。");
  }

  if (n.fatigue > 85) {
    state.status.health = Math.max(0, state.status.health - 3);
    msgs.push("😵 极度疲劳！需要休息或睡眠。");
  }

  if (n.happiness < 15) {
    msgs.push("😢 心情极度低落，做什么都提不起劲。");
  }

  for (const msg of msgs) {
    StateManager.addMessage(msg, "warning");
  }
}

/** 伤病每日结算 */
function tickHealthStatus(state) {
  const st = state.status;
  if (st.sick) {
    st.health = Math.max(0, st.health - 3);
    if (Math.random() < 0.12) {
      st.sick = false;
      StateManager.addMessage("🤒 病好了，身体恢复了。", "info");
    }
  }
  if (st.injured) {
    st.health = Math.max(0, st.health - 2);
    if (Math.random() < 0.07) {
      st.injured = false;
      StateManager.addMessage("🩹 伤好了，可以正常干活了。", "info");
    }
  }
  // 自然恢复
  if (!st.sick && !st.injured && st.health < 100) {
    st.health = Math.min(100, st.health + 1);
  }
}

/** 判定情绪状态（整合有效属性，状态互联系统） */
function determineEmotionalState(state) {
  // 使用有效属性（受状态交叉影响后的真实值）
  var effective =
    typeof getEffectiveStats === "function"
      ? getEffectiveStats(state)
      : {
          mental: state.player.mental,
          intelligence: state.player.intelligence,
        };

  const p = state.player;
  const n = state.needs;
  let score = 50;

  score += (n.happiness - 50) * 0.3;
  if (n.fatigue > 80) score -= 20;
  else if (n.fatigue > 60) score -= 10;
  else if (n.fatigue < 20) score += 5;
  if (n.hunger < 20) score -= 15;
  else if (n.hunger < 40) score -= 5;
  if (n.hygiene < 20) score -= 10;
  // 使用有效心智（状态差→心智打折→情绪更差→恶性循环）
  score += (effective.mental - 50) * 0.15;
  if (state.status.health < 30) score -= 20;
  if (state.status.injured) score -= 10;
  if (state.status.sick) score -= 8;

  let emotionalState;
  if (score < 15) emotionalState = "depressed";
  else if (score < 30) emotionalState = "sad";
  else if (score < 45) emotionalState = "stressed";
  else if (score < 60) emotionalState = "stable";
  else if (score < 80) emotionalState = "happy";
  else emotionalState = "happy";

  state.status.emotionalState = emotionalState;
  return emotionalState;
}

/** 情绪对工作的修正 */
function getEmotionWorkModifier(state) {
  const emo = state.status.emotionalState || "stable";
  const mods = {
    depressed: { pay: 0.45, injury: 2.5, skillXp: 0.3 },
    sad: { pay: 0.65, injury: 1.5, skillXp: 0.5 },
    stressed: { pay: 0.8, injury: 1.3, skillXp: 0.7 },
    stable: { pay: 1.0, injury: 1.0, skillXp: 1.0 },
    happy: { pay: 1.25, injury: 0.7, skillXp: 1.5 },
  };
  return mods[emo] || mods.stable;
}

/** 获取情绪图标 */
function getEmotionIcon(state) {
  const icons = {
    depressed: "😢",
    sad: "😔",
    stressed: "😰",
    stable: "😐",
    happy: "😊",
  };
  return icons[state.status.emotionalState] || "😐";
}

/**
 * 每日结算管线 — 声明式步骤编排
 *
 * 将 endDay 的 14 步硬编码拆为独立管线步骤，每步自声明：
 *   name: 唯一标识
 *   fn: 执行函数
 *   after: 依赖的前置步骤（可选）
 *   skipOnExtreme: 极端状态时是否跳过（默认 true）
 *
 * 架构原则：新增结算逻辑只需向 DAILY_PIPELINE 数组添加一个步骤对象，
 * 不需要修改 endDay 的主流程。
 *
 * MiniMax 友好：每个步骤的输入输出清晰，依赖声明显式化。
 */

/** 每日结算步骤管线（按顺序执行） */
const DAILY_PIPELINE = [
  // === 基础递进 ===
  {
    name: "day_increment",
    fn: function (state) {
      state.player.day++;
      state.player.actionPoints = state.player.maxActionPoints;
      state.player.timeSlot = "morning";
    },
  },

  // === 需求衰减 ===
  {
    name: "needs_decay",
    fn: function (state) {
      applyNeedsDecay(state);
    },
  },

  // === 状态交叉影响 ===
  {
    name: "status_interactions",
    fn: function (state) {
      applyStatusInteractions(state);
    },
  },

  // === 睡眠恢复 ===
  {
    name: "sleep_recovery",
    fn: function (state) {
      var house = getCurrentHousing(state);
      var recovery = house.fatigueRecovery;
      var penalty = state._fatigueRecoveryPenalty || 1.0;
      if (penalty < 1.0) {
        StateManager.addMessage(
          "😢 心情低落，睡眠质量很差，疲劳恢复减半。",
          "warning",
        );
      }
      state.needs.fatigue = Math.max(
        0,
        state.needs.fatigue - Math.round(recovery * penalty),
      );
      delete state._fatigueRecoveryPenalty;
      state.needs.hygiene = Math.min(
        100,
        state.needs.hygiene + (house.hygieneBonus || 0),
      );
      state.needs.happiness = Math.max(
        0,
        Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)),
      );
    },
  },

  // === 房租 ===
  {
    name: "rent",
    fn: function (state) {
      var house = getCurrentHousing(state);
      if (house.rent > 0) {
        if (state.resources.cash >= house.rent) {
          state.resources.cash -= house.rent;
        } else {
          StateManager.addMessage(
            "⚠️ 付不起房租 ¥" + house.rent + "！被赶回流落街头。",
            "danger",
          );
          state.housing.tier = 0;
          state.inventory.capacity =
            20 + (state.housing ? state.housing.storageCapacity || 0 : 0);
        }
      }
      if (
        state.housing &&
        state.housing.storageRented &&
        state.housing.storageCapacity > 0
      ) {
        var storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
        if (state.resources.cash >= storageRent) {
          state.resources.cash -= storageRent;
        } else {
          StateManager.addMessage("⚠️ 付不起仓库租金，仓库被收回。", "danger");
          state.housing.storageRented = false;
          state.housing.storageCapacity = 0;
          var baseCap = [20, 50, 100, 200][state.housing.tier || 0];
          state.inventory.capacity = baseCap;
        }
      }
    },
  },

  // === 健康结算 ===
  {
    name: "health_tick",
    fn: function (state) {
      tickHealthStatus(state);
    },
  },

  // === 需求阈值检查 ===
  {
    name: "needs_check",
    fn: function (state) {
      checkNeedsThresholds(state);
    },
  },

  // === 极端状态检测 ===
  {
    name: "extreme_check",
    fn: function (state) {
      var result = checkExtremeConditions(state);
      // 返回 null=正常, 'skip_day' 由调用方处理
      return result;
    },
  },

  // === 情绪判定 ===
  {
    name: "emotion",
    fn: function (state) {
      determineEmotionalState(state);
    },
  },

  // === 财务结算 ===
  {
    name: "finance",
    fn: function (state) {
      settleDailyFinance(state);
      // 成就追踪：现金归零
      if ((state.resources.cash || 0) <= 0) state.flags._everBroke = true;
    },
  },

  // === 价格更新 ===
  {
    name: "price_update",
    fn: function (state) {
      if (state.player.day - state.trade.lastPriceUpdate >= 3) {
        updateAllPrices(state);
      }
    },
  },

  // === 投资tick ===
  {
    name: "investment_tick",
    fn: function (state) {
      tickInvestmentDaily(state);
    },
  },

  // === 天气 ===
  {
    name: "weather",
    fn: function (state) {
      rollWeather(state);
    },
  },

  // === 新闻 ===
  {
    name: "news",
    fn: function (state) {
      rollDailyNews(state);
    },
  },

  // === 城管热度衰减 ===
  {
    name: "chengguan_decay",
    fn: function (state) {
      if (state.chengguan) {
        state.chengguan.heat = Math.max(
          0,
          state.chengguan.heat - 5 - Math.floor(Math.random() * 5),
        );
      }
    },
  },

  // === 清理 ===
  {
    name: "cleanup",
    fn: function (state) {
      dailyCleanup(state);
    },
  },

  // === 年龄增长 ===
  {
    name: "age",
    fn: function (state) {
      if (state.player.day % 365 === 0) {
        state.player.age++;
        StateManager.addMessage(
          "🎂 又过了一年，你现在" + state.player.age + "岁了。",
          "event",
        );
      }
    },
  },

  // === 训练次数重置 ===
  {
    name: "reset_training",
    fn: function (state) {
      if (state.flags._dailyTrainingCounts) {
        state.flags._dailyTrainingCounts = {};
      }
    },
  },

  // === 胜利判定 ===
  {
    name: "victory",
    fn: function (state) {
      checkVictoryPaths(state);
    },
  },

  // === 失败判定 ===
  {
    name: "lose",
    fn: function (state) {
      checkLoseConditions(state);
    },
  },

  // === 自动存档 ===
  {
    name: "autosave",
    fn: function (state) {
      autoSave();
    },
  },

  // === 成就检查 ===
  {
    name: "achievements",
    fn: function (state) {
      if (typeof notifyNewAchievements === "function") {
        notifyNewAchievements(state);
      }
    },
  },

  // === 结束日志 ===
  {
    name: "end_log",
    fn: function (state) {
      var emoIcon = getEmotionIcon(state);
      StateManager.addMessage(
        "🌙 第" + state.player.day + "天结束。" + emoIcon + " 新的一天开始了。",
        "info",
      );
    },
  },
];

/**
 * 执行每日结算管线。
 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
 */
function runDailyPipeline(state) {
  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
    var step = DAILY_PIPELINE[i];

    // 极端状态短路逻辑：
    // extreme_check 步骤返回 'skip_day' 时，跳过后续非核心步骤
    // 但 finance / autosave 始终执行（保证利息和存档不丢）
    if (step.name === "extreme_check") {
      var result = step.fn(state);
      if (result === "skip_day") {
        StateManager.addMessage(
          "🌙 第" + state.player.day + "天在昏迷中过去了...",
          "danger",
        );
        // 执行最后的核心步骤：财务、存档
        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
          var lateStep = DAILY_PIPELINE[j];
          if (lateStep.name === "finance" || lateStep.name === "autosave") {
            lateStep.fn(state);
          }
        }
        return; // 短路
      }
    } else {
      step.fn(state);
    }
  }
}

/**
 * endDay — 仅保留管线调度逻辑（MiniMax 友好：170行→8行）
 */
function endDay() {
  var state = StateManager.getState();
  runDailyPipeline(state);
}

