    desc: "在街边支个小摊卖烤串、煎饼果子。手艺越好，回头客越多。",
    icon: "🍢",
    location: "commercialDist",
    requirements: { minAge: 16, maxAge: 60 },
    effects: { fatigue: 16, hygiene: -5, happiness: 3, cookingXp: 4 },
