1	/**
2	 * 新手引导系统
3	 *
4	 * 首次进入游戏时弹出逐步教程，引导玩家了解基本 UI 和操作。
5	 * 用 localStorage 标记已完成引导，不会再次出现。
6	 * 可随时在帮助菜单中重新触发。
7	 */
8	
9	const TUTORIAL_KEY = "city_life_tutorial_done";
10	
11	/** 检查教程是否已完成 */
12	function isTutorialDone() {
13	  try {
14	    return localStorage.getItem(TUTORIAL_KEY) === "1";
15	  } catch (e) {
16	    return false;
17	  }
18	}
19	
20	/** 标记教程完成 */
21	function markTutorialDone() {
22	  try {
23	    localStorage.setItem(TUTORIAL_KEY, "1");
24	  } catch (e) {
25	    /* 静默 */
26	  }
27	}
28	
29	/** 重置教程（允许重新触发） */
30	function resetTutorial() {
31	  try {
32	    localStorage.removeItem(TUTORIAL_KEY);
33	  } catch (e) {
34	    /* 静默 */
35	  }
36	}
37	
38	/**
39	 * 启动新手引导
40	 * 在 startNewGame() 之后调用。
41	 */
42	function startTutorial() {
43	  if (isTutorialDone()) return;
44	
45	  const steps = [
46	    {
47	      title: "🏙️ 欢迎来到城市浮生记！",
48	      body: `
49	        <p>你带着仅有的 <strong style="color:var(--accent);">¥2,000</strong> 来到这座城市，
50	        还欠村长 <strong style="color:var(--danger);">¥5,500</strong>（日息0.3%）。</p>
