95	      body: `
96	        <p>点击顶部 <strong>"🗺️ 地图"</strong> 标签查看城市全景</p>
97	        <p>地图显示所有地点、旅行路线和当前所在位置</p>
98	        <p style="color:var(--accent);font-size:11px;">💡 最快赚钱路线：批发市场进货 → 商业区卖出赚差价！</p>
99	      `,
100	      highlight: "#tab-bar",
101	    },
102	    {
103	      title: "🎯 你准备好了！",
104	      body: `
105	        <p><strong>生存路线</strong>：废品回收 → 本钱够了去批发市场进货 → 商业区摆摊</p>
106	        <p><strong>进阶路线</strong>：提升智力到45+ → 去科技园应聘 → 职场P5→P10</p>
107	        <p><strong>关键地点</strong>：</p>
108	        <ul style="font-size:11px;color:var(--text-secondary);margin-left:16px;">
109	          <li>🏘️ 城中村 — 租房子升级住所</li>
110	          <li>📦 批发市场 — 低价进货 + 租仓库</li>
111	          <li>🏪 商业区 — 高价卖出 + 多种工作</li>
112	          <li>🏥 医院 — 看病治疗伤病</li>
113	          <li>📚 培训中心 — 学习技能考证书</li>
114	          <li>💻 科技园 — 应聘进入职场</li>
115	        </ul>
116	        <p style="color:var(--success);">祝你在这座城市混出名堂！🏆</p>
117	      `,
118	      highlight: null,
119	    },
120	  ];
121	
122	  showTutorialStep(steps, 0);
123	}
124	
125	/** 逐步展示引导 */
126	function showTutorialStep(steps, index) {
127	  if (index >= steps.length) {
128	    // 全部完成
129	    cleanupHighlight();
130	    markTutorialDone();
131	    StateManager.addMessage(
132	      "✅ 新手引导完成！点击 ❓ 帮助按钮可随时回顾。",
133	      "success",
134	    );
135	    return;
136	  }
137	
138	  const step = steps[index];
139	  const isFirst = index === 0;
140	  const isLast = index === steps.length - 1;
141	
142	  // 高亮目标区域
143	  if (step.highlight) {
144	    highlightElement(step.highlight);
145	  } else {
146	    cleanupHighlight();
147	  }
148	
149	  const buttons = [
150	    {
151	      text: isFirst ? "跳过引导" : "← 上一步",
152	      cls: isFirst ? "" : "",
153	      callback: () => {
154	        if (isFirst) {
155	          cleanupHighlight();
156	          markTutorialDone();
