1	/**
2	 * 每日结算管线 — 声明式步骤编排
3	 *
4	 * 将 endDay 的 14 步硬编码拆为独立管线步骤，每步自声明：
5	 *   name: 唯一标识
6	 *   fn: 执行函数
7	 *   after: 依赖的前置步骤（可选）
8	 *   skipOnExtreme: 极端状态时是否跳过（默认 true）
9	 *
10	 * 架构原则：新增结算逻辑只需向 DAILY_PIPELINE 数组添加一个步骤对象，
11	 * 不需要修改 endDay 的主流程。
12	 *
13	 * MiniMax 友好：每个步骤的输入输出清晰，依赖声明显式化。
14	 */
15	
16	/** 每日结算步骤管线（按顺序执行） */
17	const DAILY_PIPELINE = [
18	  // === 基础递进 ===
19	  {
20	    name: "day_increment",
21	    fn: function (state) {
22	      state.player.day++;
23	      state.player.actionPoints = state.player.maxActionPoints;
24	      state.player.timeSlot = "morning";
25	    },
26	  },
27	
28	  // === 需求衰减 ===
29	  {
30	    name: "needs_decay",
31	    fn: function (state) {
32	      applyNeedsDecay(state);
33	    },
34	  },
35	
36	  // === 状态交叉影响 ===
37	  {
38	    name: "status_interactions",
39	    fn: function (state) {
40	      applyStatusInteractions(state);
41	    },
42	  },
43	
44	  // === 睡眠恢复 ===
45	  {
46	    name: "sleep_recovery",
47	    fn: function (state) {
48	      var house = getCurrentHousing(state);
49	      var recovery = house.fatigueRecovery;
50	      var penalty = state._fatigueRecoveryPenalty || 1.0;
51	      if (penalty < 1.0) {
52	        StateManager.addMessage(
53	          "😢 心情低落，睡眠质量很差，疲劳恢复减半。",
54	          "warning",
55	        );
56	      }
57	      state.needs.fatigue = Math.max(
58	        0,
59	        state.needs.fatigue - Math.round(recovery * penalty),
60	      );
61	      delete state._fatigueRecoveryPenalty;
62	      state.needs.hygiene = Math.min(
63	        100,
64	        state.needs.hygiene + (house.hygieneBonus || 0),
65	      );
66	      state.needs.happiness = Math.max(
67	        0,
68	        Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)),
69	      );
70	    },
71	  },
72	
73	  // === 房租 ===
74	  {
75	    name: "rent",
76	    fn: function (state) {
77	      var house = getCurrentHousing(state);
78	      if (house.rent > 0) {
79	        if (state.resources.cash >= house.rent) {
80	          state.resources.cash -= house.rent;
81	        } else {
82	          StateManager.addMessage(
83	            "⚠️ 付不起房租 ¥" + house.rent + "！被赶回流落街头。",
84	            "danger",
85	          );
86	          state.housing.tier = 0;
87	          state.inventory.capacity =
88	            20 + (state.housing ? state.housing.storageCapacity || 0 : 0);
89	        }
90	      }
91	      if (
92	        state.housing &&
93	        state.housing.storageRented &&
94	        state.housing.storageCapacity > 0
95	      ) {
96	        var storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
97	        if (state.resources.cash >= storageRent) {
98	          state.resources.cash -= storageRent;
99	        } else {
100	          StateManager.addMessage("⚠️ 付不起仓库租金，仓库被收回。", "danger");
101	          state.housing.storageRented = false;
102	          state.housing.storageCapacity = 0;
103	          var baseCap = [20, 50, 100, 200][state.housing.tier || 0];
104	          state.inventory.capacity = baseCap;
105	        }
106	      }
107	    },
108	  },
109	
110	  // === 健康结算 ===
111	  {
112	    name: "health_tick",
113	    fn: function (state) {
114	      tickHealthStatus(state);
115	    },
116	  },
117	
118	  // === 需求阈值检查 ===
119	  {
120	    name: "needs_check",
121	    fn: function (state) {
122	      checkNeedsThresholds(state);
123	    },
124	  },
125	
126	  // === 极端状态检测 ===
127	  {
128	    name: "extreme_check",
129	    fn: function (state) {
130	      var result = checkExtremeConditions(state);
131	      // 返回 null=正常, 'skip_day' 由调用方处理
132	      return result;
133	    },
134	  },
135	
136	  // === 情绪判定 ===
137	  {
138	    name: "emotion",
139	    fn: function (state) {
140	      determineEmotionalState(state);
141	    },
142	  },
143	
144	  // === 财务结算 ===
145	  {
146	    name: "finance",
147	    fn: function (state) {
148	      settleDailyFinance(state);
149	      // 成就追踪：现金归零
150	      if ((state.resources.cash || 0) <= 0) state.flags._everBroke = true;
151	    },
152	  },
153	
154	  // === 价格更新 ===
155	  {
156	    name: "price_update",
157	    fn: function (state) {
158	      if (state.player.day - state.trade.lastPriceUpdate >= 3) {
159	        updateAllPrices(state);
160	      }
161	    },
162	  },
163	
164	  // === 投资tick ===
165	  {
166	    name: "investment_tick",
167	    fn: function (state) {
168	      tickInvestmentDaily(state);
169	    },
170	  },
171	
172	  // === 天气 ===
173	  {
174	    name: "weather",
175	    fn: function (state) {
176	      rollWeather(state);
177	    },
178	  },
179	
180	  // === 节日效果 ===
181	  {
182	    name: "festival",
183	    fn: function (state) {
184	      if (typeof checkFestivalDailyEffects === "function") {
185	        checkFestivalDailyEffects(state);
186	      }
187	    },
188	  },
189	
190	  // === 新闻 ===
191	  {
192	    name: "news",
193	    fn: function (state) {
194	      rollDailyNews(state);
195	    },
196	  },
197	
198	  // === 城管热度衰减 ===
199	  {
200	    name: "chengguan_decay",
201	    fn: function (state) {
202	      if (state.chengguan) {
203	        state.chengguan.heat = Math.max(
204	          0,
205	          state.chengguan.heat - 5 - Math.floor(Math.random() * 5),
206	        );
207	      }
208	    },
209	  },
210	
211	  // === 清理 ===
212	  {
213	    name: "cleanup",
214	    fn: function (state) {
215	      dailyCleanup(state);
216	    },
217	  },
218	
219	  // === 年龄增长 ===
220	  {
221	    name: "age",
222	    fn: function (state) {
223	      if (state.player.day % 365 === 0) {
224	        state.player.age++;
225	        StateManager.addMessage(
226	          "🎂 又过了一年，你现在" + state.player.age + "岁了。",
227	          "event",
228	        );
229	      }
230	    },
231	  },
232	
233	  // === 训练次数重置 ===
234	  {
235	    name: "reset_training",
236	    fn: function (state) {
237	      if (state.flags._dailyTrainingCounts) {
238	        state.flags._dailyTrainingCounts = {};
239	      }
240	    },
241	  },
242	
243	  // === 胜利判定 ===
244	  {
245	    name: "victory",
246	    fn: function (state) {
247	      checkVictoryPaths(state);
248	    },
249	  },
250	
251	  // === 失败判定 ===
252	  {
253	    name: "lose",
254	    fn: function (state) {
255	      checkLoseConditions(state);
256	    },
257	  },
258	
259	  // === 自动存档 ===
260	  {
261	    name: "autosave",
262	    fn: function (state) {
263	      autoSave();
264	    },
265	  },
266	
267	  // === 成就检查 ===
268	  {
269	    name: "achievements",
270	    fn: function (state) {
271	      if (typeof notifyNewAchievements === "function") {
272	        notifyNewAchievements(state);
273	      }
274	    },
275	  },
276	
277	  // === 梦想进度检查 ===
278	  {
279	    name: "dream_check",
280	    fn: function (state) {
281	      if (typeof checkDreamProgress === "function") {
282	        checkDreamProgress(state);
283	      }
284	    },
285	  },
286	
287	  // === 结束日志 ===
288	  {
289	    name: "end_log",
290	    fn: function (state) {
291	      var emoIcon = getEmotionIcon(state);
292	      StateManager.addMessage(
293	        "🌙 第" + state.player.day + "天结束。" + emoIcon + " 新的一天开始了。",
294	        "info",
295	      );
296	    },
297	  },
298	];
299	
300	/**
301	 * 执行每日结算管线。
302	 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
303	 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
304	 */
305	function runDailyPipeline(state) {
306	  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
307	    var step = DAILY_PIPELINE[i];
308	
309	    // 极端状态短路逻辑：
310	    // extreme_check 步骤返回 'skip_day' 时，跳过后续非核心步骤
311	    // 但 finance / autosave 始终执行（保证利息和存档不丢）
312	    if (step.name === "extreme_check") {
313	      var result = step.fn(state);
314	      if (result === "skip_day") {
315	        StateManager.addMessage(
316	          "🌙 第" + state.player.day + "天在昏迷中过去了...",
317	          "danger",
318	        );
319	        // 执行最后的核心步骤：财务、存档
320	        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
321	          var lateStep = DAILY_PIPELINE[j];
322	          if (lateStep.name === "finance" || lateStep.name === "autosave") {
323	            lateStep.fn(state);
324	          }
325	        }
326	        return; // 短路
327	      }
328	    } else {
329	      step.fn(state);
330	    }
331	  }
