1	/**
2	 * 存档系统 — localStorage 多槽位持久化
3	 *
4	 * 5个手动存档槽 + 1个自动存档
5	 * 索引键: 'city_life_story_index' — 存储各槽位元信息
6	 * 存档键: 'city_life_story_slot_N' (N=1..5) + 'city_life_story_autosave'
7	 */
8	
9	const NUM_SLOTS = 5;
10	const SLOT_PREFIX = "city_life_story_slot_";
11	const AUTO_SAVE_KEY = "city_life_story_autosave";
12	const INDEX_KEY = "city_life_story_index";
13	
14	/** 获取槽位键 */
15	function slotKey(n) {
16	  return SLOT_PREFIX + n;
17	}
18	
19	/** 读取存档索引 */
20	function getSaveIndex() {
21	  try {
22	    const raw = localStorage.getItem(INDEX_KEY);
23	    return raw ? JSON.parse(raw) : {};
24	  } catch (e) {
25	    return {};
26	  }
27	}
28	
29	/** 写入存档索引 */
30	function setSaveIndex(index) {
31	  localStorage.setItem(INDEX_KEY, JSON.stringify(index));
32	}
33	
34	/** 保存游戏到指定槽位（1-5） */
35	function saveGame(slot) {
36	  if (slot < 1 || slot > NUM_SLOTS) {
37	    StateManager.addMessage("⚠️ 无效的存档槽位。", "danger");
38	    return false;
39	  }
40	
41	  try {
42	    const state = StateManager.getState();
43	    state.lastPlayedAt = Date.now();
44	
45	    const saveData = JSON.parse(JSON.stringify(state));
46	    // 精简消息日志
47	    if (saveData.messageLog && saveData.messageLog.length > 200) {
48	      saveData.messageLog = saveData.messageLog.slice(-200);
49	    }
50	
51	    localStorage.setItem(slotKey(slot), JSON.stringify(saveData));
52	
53	    // 更新索引
54	    const index = getSaveIndex();
55	    index[slot] = {
56	      day: state.player.day,
57	      phase: state.player.phase,
58	      cash: state.resources.cash,
59	      age: state.player.age,
60	      debt: state.resources.debt,
61	      totalEarned: state.resources.totalEarned,
62	      location: state.trade.currentLocation,
63	      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
64	      savedAt: Date.now(),
65	    };
66	    setSaveIndex(index);
67	
68	    StateManager.addMessage(
69	      `💾 已保存到槽位 ${slot}（第${state.player.day}天，¥${state.resources.cash.toLocaleString()}）`,
70	      "success",
71	    );
72	    return true;
73	  } catch (e) {
74	    console.error("存档失败:", e);
75	    StateManager.addMessage("⚠️ 存档失败: " + e.message, "danger");
76	    return false;
77	  }
78	}
79	
80	/** 自动存档 */
81	function autoSave() {
82	  try {
83	    const state = StateManager.getState();
84	    const saveData = JSON.parse(JSON.stringify(state));
85	    saveData.lastPlayedAt = Date.now();
86	    if (saveData.messageLog && saveData.messageLog.length > 200) {
87	      saveData.messageLog = saveData.messageLog.slice(-200);
88	    }
89	    localStorage.setItem(AUTO_SAVE_KEY, JSON.stringify(saveData));
90	
91	    // 更新索引中的自动存档信息
92	    const index = getSaveIndex();
93	    index._auto = {
94	      day: state.player.day,
95	      phase: state.player.phase,
96	      cash: state.resources.cash,
97	      age: state.player.age,
98	      debt: state.resources.debt,
99	      totalEarned: state.resources.totalEarned,
100	      location: state.trade.currentLocation,
101	      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
102	      savedAt: Date.now(),
103	    };
104	    setSaveIndex(index);
105	  } catch (e) {
106	    /* 静默 */
107	  }
108	}
109	
110	/** 从指定槽位加载存档 */
111	function loadGame(slot) {
112	  try {
113	    let key;
114	    if (slot === "_auto") {
115	      key = AUTO_SAVE_KEY;
116	    } else if (typeof slot === "number" && slot >= 1 && slot <= NUM_SLOTS) {
117	      key = slotKey(slot);
118	    } else {
119	      // 兼容旧版：尝试直接以 slot 为键
120	      key = slot;
121	    }
122	
123	    const json = localStorage.getItem(key);
124	    if (!json) return null;
125	    return JSON.parse(json);
126	  } catch (e) {
127	    console.error("读档失败:", e);
128	    return null;
129	  }
130	}
131	
132	/** 删除指定槽位的存档 */
133	function deleteSave(slot) {
134	  if (slot === "_auto") {
135	    localStorage.removeItem(AUTO_SAVE_KEY);
136	    const index = getSaveIndex();
137	    delete index._auto;
138	    setSaveIndex(index);
139	    return;
140	  }
141	  if (slot < 1 || slot > NUM_SLOTS) return;
142	  localStorage.removeItem(slotKey(slot));
143	  const index = getSaveIndex();
144	  delete index[slot];
145	  setSaveIndex(index);
146	}
147	
148	/** 检查指定槽位是否有存档 */
149	function hasSave(slot) {
150	  if (slot === "_auto") return localStorage.getItem(AUTO_SAVE_KEY) !== null;
151	  if (typeof slot === "number")
152	    return localStorage.getItem(slotKey(slot)) !== null;
153	  // 兼容检查任意存档
154	  const index = getSaveIndex();
155	  return Object.keys(index).length > 0;
156	}
157	
158	/** 获取存档槽位的显示信息 */
159	function getSlotInfo(slot) {
160	  if (slot === "_auto") {
161	    const index = getSaveIndex();
162	    const meta = index._auto;
163	    if (!meta) {
164	      const raw = localStorage.getItem(AUTO_SAVE_KEY);
165	      if (!raw) return null;
166	      try {
167	        const data = JSON.parse(raw);
168	        return {
169	          day: data.player?.day || 1,
170	          phase: data.player?.phase || "street",
171	          cash: data.resources?.cash || 0,
172	          age: data.player?.age || 20,
173	          debt: data.resources?.debt || 0,
174	          totalEarned: data.resources?.totalEarned || 0,
175	          location: data.trade?.currentLocation || "slum",
176	          rank:
177	            data.player?.phase === "corporate" ? data.corporate?.rank : null,
178	          savedAt: data.lastPlayedAt || data.createdAt,
179	        };
180	      } catch (e) {
181	        return null;
182	      }
183	    }
184	    return { ...meta, slot: "_auto", label: "🤖 自动存档" };
185	  }
186	
187	  const index = getSaveIndex();
188	  const meta = index[slot];
189	  if (!meta) return null;
190	
191	  const date = new Date(meta.savedAt);
192	  const loc =
193	    typeof LOCATIONS !== "undefined" && LOCATIONS[meta.location]
194	      ? LOCATIONS[meta.location].name
195	      : meta.location;
196	
197	  return {
198	    slot,
199	    label: `存档槽位 ${slot}`,
200	    day: meta.day,
201	    phase: meta.phase,
202	    cash: meta.cash,
203	    age: meta.age,
204	    debt: meta.debt,
205	    totalEarned: meta.totalEarned,
206	    location: loc,
207	    rank: meta.rank,
208	    date: date.toLocaleString("zh-CN"),
209	    savedAt: meta.savedAt,
210	  };
211	}
212	
213	/** 获取所有存档槽位信息 */
214	function getAllSlots() {
215	  const slots = [];
216	  // 自动存档
217	  const auto = getSlotInfo("_auto");
218	  if (auto) slots.push(auto);
219	  // 手动存档 1-5
220	  for (let i = 1; i <= NUM_SLOTS; i++) {
221	    const info = getSlotInfo(i);
222	    if (info) slots.push(info);
223	  }
224	  return slots;
225	}
226	
227	/** 获取所有槽位（含空槽位） */
228	function getAllSlotsWithEmpty() {
229	  const slots = [];
230	  // 自动存档
231	  const auto = getSlotInfo("_auto");
232	  slots.push(auto || { slot: "_auto", label: "🤖 自动存档", empty: true });
233	  // 手动存档
234	  for (let i = 1; i <= NUM_SLOTS; i++) {
235	    const info = getSlotInfo(i);
236	    slots.push(info || { slot: i, label: `存档槽位 ${i}`, empty: true });
237	  }
238	  return slots;
239	}
240	
241	/** 导出存档（用于备份） */
242	function exportSave(slot) {
243	  const data = loadGame(slot || "_auto");
244	  if (!data) return null;
245	  return JSON.stringify(data, null, 2);
246	}
247	
248	/** 导入存档 */
249	function importSave(jsonStr) {
250	  try {
251	    const data = JSON.parse(jsonStr);
252	    if (!data.version || !data.player) {
253	      throw new Error("无效的存档格式");
254	    }
255	    StateManager.importState(data);
256	    StateManager.addMessage("📥 存档导入成功！", "success");
257	    return true;
258	  } catch (e) {
259	    StateManager.addMessage("⚠️ 存档导入失败: " + e.message, "danger");
260	    return false;
261	  }
262	}
263	
264	// 全局挂载
265	if (typeof window !== "undefined") {
266	  Object.assign(window, {
267	    saveGame,
268	    loadGame,
269	    deleteSave,
270	    hasSave,
271	    autoSave,
272	    getSlotInfo,
273	    getAllSlots,
274	    getAllSlotsWithEmpty,
275	    exportSave,
276	    importSave,
277	    NUM_SLOTS,
278	    SLOT_PREFIX,
279	    AUTO_SAVE_KEY,
280	    INDEX_KEY,
281	    slotKey,
282	    getSaveIndex,
283	    setSaveIndex,
284	  });
285	}
