/**
 * 每日结算管线 — 声明式步骤编排
 *
 * 将 endDay 的 14 步硬编码拆为独立管线步骤，每步自声明：
 *   name: 唯一标识
 *   fn: 执行函数
 *   after: 依赖的前置步骤（可选）
 *   skipOnExtreme: 极端状态时是否跳过（默认 true）
 *
 * 架构原则：新增结算逻辑只需向 DAILY_PIPELINE 数组添加一个步骤对象，
 * 不需要修改 endDay 的主流程。
 *
 * MiniMax 友好：每个步骤的输入输出清晰，依赖声明显式化。
 */

/** 每日结算步骤管线（按顺序执行） */
const DAILY_PIPELINE = [
  // === 基础递进 ===
  {
    name: "day_increment",
    fn: function (state) {
      state.player.day++;
      state.player.actionPoints = state.player.maxActionPoints;
      state.player.timeSlot = "morning";
    },
  },

  // === 需求衰减 ===
  {
    name: "needs_decay",
    fn: function (state) {
      applyNeedsDecay(state);
    },
  },

  // === 状态交叉影响 ===
  {
    name: "status_interactions",
    fn: function (state) {
      applyStatusInteractions(state);
    },
  },

  // === 睡眠恢复 ===
  {
    name: "sleep_recovery",
    fn: function (state) {
      var house = getCurrentHousing(state);
      var recovery = house.fatigueRecovery;
      var penalty = state._fatigueRecoveryPenalty || 1.0;
      if (penalty < 1.0) {
        StateManager.addMessage(
          "😢 心情低落，睡眠质量很差，疲劳恢复减半。",
          "warning",
        );
      }
      state.needs.fatigue = Math.max(
        0,
        state.needs.fatigue - Math.round(recovery * penalty),
      );
      delete state._fatigueRecoveryPenalty;
      state.needs.hygiene = Math.min(
        100,
        state.needs.hygiene + (house.hygieneBonus || 0),
      );
      state.needs.happiness = Math.max(
        0,
        Math.min(100, state.needs.happiness - 3 + (house.happinessBonus || 0)),
      );
    },
  },

  // === 房租 ===
  {
    name: "rent",
    fn: function (state) {
      var house = getCurrentHousing(state);
      if (house.rent > 0) {
        if (state.resources.cash >= house.rent) {
          state.resources.cash -= house.rent;
        } else {
          StateManager.addMessage(
            "⚠️ 付不起房租 ¥" + house.rent + "！被赶回流落街头。",
            "danger",
          );
          state.housing.tier = 0;
          state.inventory.capacity =
            20 + (state.housing ? state.housing.storageCapacity || 0 : 0);
        }
      }
      if (
        state.housing &&
        state.housing.storageRented &&
        state.housing.storageCapacity > 0
      ) {
        var storageRent = state.housing.storageCapacity >= 500 ? 50 : 20;
        if (state.resources.cash >= storageRent) {
          state.resources.cash -= storageRent;
        } else {
          StateManager.addMessage("⚠️ 付不起仓库租金，仓库被收回。", "danger");
          state.housing.storageRented = false;
          state.housing.storageCapacity = 0;
          var baseCap = [20, 50, 100, 200][state.housing.tier || 0];
          state.inventory.capacity = baseCap;
        }
      }
    },
  },

  // === 健康结算 ===
  {
    name: "health_tick",
    fn: function (state) {
      tickHealthStatus(state);
    },
  },

  // === 需求阈值检查 ===
  {
    name: "needs_check",
    fn: function (state) {
      checkNeedsThresholds(state);
    },
  },

  // === 极端状态检测 ===
  {
    name: "extreme_check",
    fn: function (state) {
      var result = checkExtremeConditions(state);
      // 返回 null=正常, 'skip_day' 由调用方处理
      return result;
    },
  },

  // === 情绪判定 ===
  {
    name: "emotion",
    fn: function (state) {
      determineEmotionalState(state);
    },
  },

  // === 财务结算 ===
  {
    name: "finance",
    fn: function (state) {
      settleDailyFinance(state);
      // 成就追踪：现金归零
      if ((state.resources.cash || 0) <= 0) state.flags._everBroke = true;
    },
  },

  // === 每日快照（用于成长图表） ===
  {
    name: "snapshot",
    fn: function (state) {
      if (!state.flags._cashHistory) state.flags._cashHistory = [];
      var totalAsset =
        (state.resources.cash || 0) + (state.resources.bankBalance || 0);
      state.flags._cashHistory.push({
        day: state.player.day,
        value: totalAsset,
      });
      if (state.flags._cashHistory.length > 90) {
        state.flags._cashHistory = state.flags._cashHistory.slice(-90);
      }
    },
  },

  // === 价格更新 ===
  {
    name: "price_update",
    fn: function (state) {
      if (state.player.day - state.trade.lastPriceUpdate >= 3) {
        updateAllPrices(state);
      }
    },
  },

  // === 投资tick ===
  {
    name: "investment_tick",
    fn: function (state) {
      tickInvestmentDaily(state);
    },
  },

  // === 天气 ===
  {
    name: "weather",
    fn: function (state) {
      rollWeather(state);
    },
  },

  // === 节日效果 ===
  {
    name: "festival",
    fn: function (state) {
      if (typeof checkFestivalDailyEffects === "function") {
        checkFestivalDailyEffects(state);
      }
    },
  },

  // === 新闻 ===
  {
    name: "news",
    fn: function (state) {
      rollDailyNews(state);
    },
  },

  // === 城管热度衰减 ===
  {
    name: "chengguan_decay",
    fn: function (state) {
      if (state.chengguan) {
        state.chengguan.heat = Math.max(
          0,
          state.chengguan.heat - 5 - Math.floor(Math.random() * 5),
        );
      }
    },
  },

  // === 清理 ===
  {
    name: "cleanup",
    fn: function (state) {
      dailyCleanup(state);
    },
  },

  // === 年龄增长 ===
  {
    name: "age",
    fn: function (state) {
      if (state.player.day % 365 === 0) {
        state.player.age++;
        StateManager.addMessage(
          "🎂 又过了一年，你现在" + state.player.age + "岁了。",
          "event",
        );
      }
    },
  },

  // === 训练次数重置 ===
  {
    name: "reset_training",
    fn: function (state) {
      if (state.flags._dailyTrainingCounts) {
        state.flags._dailyTrainingCounts = {};
      }
    },
  },

  // === 胜利判定 ===
  {
    name: "victory",
    fn: function (state) {
      checkVictoryPaths(state);
    },
  },

  // === 失败判定 ===
  {
    name: "lose",
    fn: function (state) {
      checkLoseConditions(state);
    },
  },

  // === 自动存档 ===
  {
    name: "autosave",
    fn: function (state) {
      autoSave();
    },
  },

  // === 成就检查 ===
  {
    name: "achievements",
    fn: function (state) {
      if (typeof notifyNewAchievements === "function") {
        notifyNewAchievements(state);
      }
    },
  },

  // === 梦想进度检查 ===
  {
    name: "dream_check",
    fn: function (state) {
      if (typeof checkDreamProgress === "function") {
        checkDreamProgress(state);
      }
    },
  },

  // === 动态教程提示 ===
  {
    name: "hint_check",
    fn: function (state) {
      if (typeof checkDynamicHints === "function") {
        checkDynamicHints(state);
      }
    },
  },

  // === 结束日志 ===
  {
    name: "end_log",
    fn: function (state) {
      var emoIcon = getEmotionIcon(state);
      StateManager.addMessage(
        "🌙 第" + state.player.day + "天结束。" + emoIcon + " 新的一天开始了。",
        "info",
      );
      // 今日总结（仅街头阶段，职场有自己的季末总结）
      if (state.player.phase === "street") {
        var summary = generateDailySummary(
          state,
          state.flags._dayStartCash || 0,
          state.flags._dayStartHealth || 100,
          state.flags._dayStartHappiness || 0,
        );
        StateManager.addMessage(summary, "hint");
      }
    },
  },
];

/** 生成每日一句话总结 */
function generateDailySummary(state, startCash, startHealth, startHappiness) {
  var cash = state.resources.cash || 0;
  var bank = state.resources.bankBalance || 0;
  var delta = cash - startCash;
  var healthDrop = startHealth - ((state.status && state.status.health) || 100);
  var happyDrop =
    startHappiness - ((state.needs && state.needs.happiness) || 0);

  var highlights = [];

  // 财务总结
  if (delta >= 500) {
    highlights.push("今天大丰收，净赚了¥" + delta.toLocaleString());
  } else if (delta >= 100) {
    highlights.push("今天赚了¥" + delta.toLocaleString() + "，小有收获");
  } else if (delta >= 0) {
    highlights.push("今天收支基本持平");
  } else if (delta < -200) {
    highlights.push(
      "今天支出比收入多了¥" + Math.abs(delta).toLocaleString() + "，要节省一点",
    );
  } else {
    highlights.push("今天支出略多于收入");
  }

  // 健康/状态提示
  if (healthDrop >= 10) {
    highlights.push("健康下降了不少");
  }
  if (happyDrop >= 15) {
    highlights.push("心情差了很多，注意调整");
  }

  // 银行存款有利息
  if (bank > 0) {
    highlights.push("银行里的¥" + bank.toLocaleString() + "还在生息");
  }

  // 节日
  if (typeof getCurrentFestival === "function") {
    var fest = getCurrentFestival(state.player.day);
    if (fest) highlights.push(fest.icon + " " + fest.name + "气氛浓厚");
  }

  var summary = highlights.slice(0, 2).join("，") + "。";
  return "📋 今日总结：" + summary;
}

/**
 * 执行每日结算管线。
 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
 */
function runDailyPipeline(state) {
  // 记录日始状态用于今日总结（存入 state.flags 供 end_log fn 读取）
  state.flags._dayStartCash = state.resources.cash || 0;
  state.flags._dayStartHealth = (state.status && state.status.health) || 100;
  state.flags._dayStartHappiness = (state.needs && state.needs.happiness) || 0;

  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
    var step = DAILY_PIPELINE[i];

    // 极端状态短路逻辑：
    // extreme_check 步骤返回 'skip_day' 时，跳过后续非核心步骤
    // 但 finance / autosave 始终执行（保证利息和存档不丢）
    if (step.name === "extreme_check") {
      var result = step.fn(state);
      if (result === "skip_day") {
        StateManager.addMessage(
          "🌙 第" + state.player.day + "天在昏迷中过去了...",
          "danger",
        );
        // 执行最后的核心步骤：财务、存档
        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
          var lateStep = DAILY_PIPELINE[j];
          if (lateStep.name === "finance" || lateStep.name === "autosave") {
            lateStep.fn(state);
          }
        }
        return; // 短路
      }
    } else {
      step.fn(state);
    }
  }
}

/**
 * endDay — 仅保留管线调度逻辑（MiniMax 友好：170行→8行）
 */
function endDay() {
  var state = StateManager.getState();
  runDailyPipeline(state);
}

/**
 * 存档系统 — localStorage 多槽位持久化
 *
 * 5个手动存档槽 + 1个自动存档
 * 索引键: 'city_life_story_index' — 存储各槽位元信息
 * 存档键: 'city_life_story_slot_N' (N=1..5) + 'city_life_story_autosave'
 */

const NUM_SLOTS = 5;
const SLOT_PREFIX = "city_life_story_slot_";
const AUTO_SAVE_KEY = "city_life_story_autosave";
const INDEX_KEY = "city_life_story_index";

/** 获取槽位键 */
function slotKey(n) {
  return SLOT_PREFIX + n;
}

/** 读取存档索引 */
function getSaveIndex() {
  try {
    const raw = localStorage.getItem(INDEX_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

/** 写入存档索引 */
function setSaveIndex(index) {
  localStorage.setItem(INDEX_KEY, JSON.stringify(index));
}

/** 生成"那时候你..."回忆文案（存储于索引，读档时展示） */
function generateSaveNarrative(state) {
  var p = state.player;
  var r = state.resources;
  var day = p.day;
  var cash = (r.cash || 0) + (r.bankBalance || 0);
  var debt = r.villageDebt || r.debt || 0;

  var locNames = {
    slum: "城中村",
    wholesaleMarket: "批发市场",
    construction: "建筑工地",
    factoryZone: "工厂区",
    school: "大学城",
    commercialDist: "商业区",
    techPark: "科技园",
    hospital: "医院",
    bank: "银行",
    park: "公园",
    trainingCenter: "培训中心",
  };
  var loc = locNames[state.trade && state.trade.currentLocation] || "城市某处";

  if (p.phase === "corporate") {
    var rank = (state.corporate && state.corporate.rank) || "P5";
    var company = (state.corporate && state.corporate.company) || "科技公司";
    return (
      "那时候你已经是" +
      company +
      "的" +
      rank +
      "，在职场打拼了" +
      day +
      "天，存款" +
      (cash >= 1000 ? (cash / 1000).toFixed(1) + "万" : "¥" + cash) +
      "元。"
    );
  }

  var tail = "";
  var dreamId = state.flags && state.flags._dreamId;
  if (dreamId) {
    var dreamNames = {
      restaurant: "开餐馆",
      apartment: "买房",
      abroad: "出国",
      investor: "投资大亨",
      celebrity: "城市名人",
    };
    tail = "，梦想着" + (dreamNames[dreamId] || dreamId);
  }

  if (day <= 15) {
    return (
      "那时候你刚来这座城市第" +
      day +
      "天，在" +
      loc +
      "落脚，兜里" +
      (debt > 0
        ? "还欠着¥" + debt.toLocaleString() + "的债"
        : "有¥" + cash.toLocaleString()) +
      tail +
      "。"
    );
  } else if (cash < 500) {
    return (
      "那时候你在城里漂了" +
      day +
      "天，手里只剩¥" +
      cash.toLocaleString() +
      "，日子过得很紧巴" +
      tail +
      "。"
    );
  } else if (cash >= 50000) {
    return (
      "那时候你在" +
      loc +
      "打拼了" +
      day +
      "天，已经攒下" +
      Math.round(cash / 1000) +
      "千元，离梦想越来越近" +
      tail +
      "。"
    );
  } else {
    return (
      "那时候你在城里走过了" +
      day +
      "天，在" +
      loc +
      "一步一步往前走，手里有¥" +
      cash.toLocaleString() +
      tail +
      "。"
    );
  }
}

/** 保存游戏到指定槽位（1-5） */
function saveGame(slot) {
  if (slot < 1 || slot > NUM_SLOTS) {
    StateManager.addMessage("⚠️ 无效的存档槽位。", "danger");
    return false;
  }

  try {
    const state = StateManager.getState();
    state.lastPlayedAt = Date.now();

    const saveData = JSON.parse(JSON.stringify(state));
    // 精简消息日志
    if (saveData.messageLog && saveData.messageLog.length > 200) {
      saveData.messageLog = saveData.messageLog.slice(-200);
    }

    localStorage.setItem(slotKey(slot), JSON.stringify(saveData));

    // 更新索引
    const index = getSaveIndex();
    index[slot] = {
      day: state.player.day,
      phase: state.player.phase,
      cash: state.resources.cash,
      age: state.player.age,
      debt: state.resources.debt,
      totalEarned: state.resources.totalEarned,
      location: state.trade.currentLocation,
      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
      savedAt: Date.now(),
      narrative: generateSaveNarrative(state),
    };
    setSaveIndex(index);

    StateManager.addMessage(
      `💾 已保存到槽位 ${slot}（第${state.player.day}天，¥${state.resources.cash.toLocaleString()}）`,
      "success",
    );
    return true;
  } catch (e) {
    console.error("存档失败:", e);
    StateManager.addMessage("⚠️ 存档失败: " + e.message, "danger");
    return false;
  }
}

/** 自动存档 */
function autoSave() {
  try {
    const state = StateManager.getState();
    const saveData = JSON.parse(JSON.stringify(state));
    saveData.lastPlayedAt = Date.now();
    if (saveData.messageLog && saveData.messageLog.length > 200) {
      saveData.messageLog = saveData.messageLog.slice(-200);
    }
    localStorage.setItem(AUTO_SAVE_KEY, JSON.stringify(saveData));

    // 更新索引中的自动存档信息
    const index = getSaveIndex();
    index._auto = {
      day: state.player.day,
      phase: state.player.phase,
      cash: state.resources.cash,
      age: state.player.age,
      debt: state.resources.debt,
      totalEarned: state.resources.totalEarned,
      location: state.trade.currentLocation,
      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
      savedAt: Date.now(),
      narrative: generateSaveNarrative(state),
    };
    setSaveIndex(index);
  } catch (e) {
    /* 静默 */
  }
}

/** 从指定槽位加载存档 */
function loadGame(slot) {
  try {
    let key;
    if (slot === "_auto") {
      key = AUTO_SAVE_KEY;
    } else if (typeof slot === "number" && slot >= 1 && slot <= NUM_SLOTS) {
      key = slotKey(slot);
    } else {
      // 兼容旧版：尝试直接以 slot 为键
      key = slot;
    }

    const json = localStorage.getItem(key);
    if (!json) return null;
    return JSON.parse(json);
  } catch (e) {
    console.error("读档失败:", e);
    return null;
  }
}

/** 删除指定槽位的存档 */
function deleteSave(slot) {
  if (slot === "_auto") {
    localStorage.removeItem(AUTO_SAVE_KEY);
    const index = getSaveIndex();
    delete index._auto;
    setSaveIndex(index);
    return;
  }
  if (slot < 1 || slot > NUM_SLOTS) return;
  localStorage.removeItem(slotKey(slot));
  const index = getSaveIndex();
  delete index[slot];
  setSaveIndex(index);
}

/** 检查指定槽位是否有存档 */
function hasSave(slot) {
  if (slot === "_auto") return localStorage.getItem(AUTO_SAVE_KEY) !== null;
  if (typeof slot === "number")
    return localStorage.getItem(slotKey(slot)) !== null;
  // 兼容检查任意存档
  const index = getSaveIndex();
  return Object.keys(index).length > 0;
}

/** 获取存档槽位的显示信息 */
function getSlotInfo(slot) {
  if (slot === "_auto") {
    const index = getSaveIndex();
    const meta = index._auto;
    if (!meta) {
      const raw = localStorage.getItem(AUTO_SAVE_KEY);
      if (!raw) return null;
      try {
        const data = JSON.parse(raw);
        return {
          day: data.player?.day || 1,
          phase: data.player?.phase || "street",
          cash: data.resources?.cash || 0,
          age: data.player?.age || 20,
          debt: data.resources?.debt || 0,
          totalEarned: data.resources?.totalEarned || 0,
          location: data.trade?.currentLocation || "slum",
          rank:
            data.player?.phase === "corporate" ? data.corporate?.rank : null,
          savedAt: data.lastPlayedAt || data.createdAt,
        };
      } catch (e) {
        return null;
      }
    }
    return { ...meta, slot: "_auto", label: "🤖 自动存档" };
  }

  const index = getSaveIndex();
  const meta = index[slot];
  if (!meta) return null;

  const date = new Date(meta.savedAt);
  const loc =
    typeof LOCATIONS !== "undefined" && LOCATIONS[meta.location]
      ? LOCATIONS[meta.location].name
      : meta.location;

  return {
    slot,
    label: `存档槽位 ${slot}`,
    day: meta.day,
    phase: meta.phase,
    cash: meta.cash,
    age: meta.age,
    debt: meta.debt,
    totalEarned: meta.totalEarned,
    location: loc,
    rank: meta.rank,
    date: date.toLocaleString("zh-CN"),
    savedAt: meta.savedAt,
  };
}

/** 获取所有存档槽位信息 */
function getAllSlots() {
  const slots = [];
  // 自动存档
  const auto = getSlotInfo("_auto");
  if (auto) slots.push(auto);
  // 手动存档 1-5
  for (let i = 1; i <= NUM_SLOTS; i++) {
    const info = getSlotInfo(i);
    if (info) slots.push(info);
  }
  return slots;
}

/** 获取所有槽位（含空槽位） */
function getAllSlotsWithEmpty() {
  const slots = [];
  // 自动存档
  const auto = getSlotInfo("_auto");
  slots.push(auto || { slot: "_auto", label: "🤖 自动存档", empty: true });
  // 手动存档
  for (let i = 1; i <= NUM_SLOTS; i++) {
    const info = getSlotInfo(i);
    slots.push(info || { slot: i, label: `存档槽位 ${i}`, empty: true });
  }
  return slots;
}

/** 导出存档（用于备份） */
function exportSave(slot) {
  const data = loadGame(slot || "_auto");
  if (!data) return null;
  return JSON.stringify(data, null, 2);
}

/** 导入存档 */
function importSave(jsonStr) {
  try {
    const data = JSON.parse(jsonStr);
    if (!data.version || !data.player) {
      throw new Error("无效的存档格式");
    }
    StateManager.importState(data);
    StateManager.addMessage("📥 存档导入成功！", "success");
    return true;
  } catch (e) {
    StateManager.addMessage("⚠️ 存档导入失败: " + e.message, "danger");
    return false;
  }
}

// 全局挂载
if (typeof window !== "undefined") {
  Object.assign(window, {
    saveGame,
    loadGame,
    deleteSave,
    hasSave,
    autoSave,
    getSlotInfo,
    getAllSlots,
    getAllSlotsWithEmpty,
    exportSave,
    importSave,
    NUM_SLOTS,
    SLOT_PREFIX,
    AUTO_SAVE_KEY,
    INDEX_KEY,
    slotKey,
    getSaveIndex,
    setSaveIndex,
  });
}

/**
 * 新手引导系统
 *
 * 首次进入游戏时弹出逐步教程，引导玩家了解基本 UI 和操作。
 * 用 localStorage 标记已完成引导，不会再次出现。
 * 可随时在帮助菜单中重新触发。
 */

const TUTORIAL_KEY = "city_life_tutorial_done";

/** 检查教程是否已完成 */
function isTutorialDone() {
  try {
    return localStorage.getItem(TUTORIAL_KEY) === "1";
  } catch (e) {
    return false;
  }
}

/** 标记教程完成 */
function markTutorialDone() {
  try {
    localStorage.setItem(TUTORIAL_KEY, "1");
  } catch (e) {
    /* 静默 */
  }
}

/** 重置教程（允许重新触发） */
function resetTutorial() {
  try {
    localStorage.removeItem(TUTORIAL_KEY);
  } catch (e) {
    /* 静默 */
  }
}

/**
 * 启动新手引导
 * 在 startNewGame() 之后调用。
 */
function startTutorial() {
  if (isTutorialDone()) return;

  const steps = [
    {
      title: "🏙️ 欢迎来到城市浮生记！",
      body: `
        <p>你带着仅有的 <strong style="color:var(--accent);">¥2,000</strong> 来到这座城市，
        还欠村长 <strong style="color:var(--danger);">¥5,500</strong>（日息0.3%）。</p>
        <p>目标：<strong>活下去，活出个人样来！</strong></p>
        <p style="color:var(--text-secondary);font-size:11px;">🗑️ 废品回收 → 🛒 进货倒卖 → 💼 应聘职场 → 🏆 P10合伙人</p>
        <p style="color:var(--success);">接下来用30秒带你快速上手 ⬇️</p>
      `,
      highlight: null,
    },
    {
