    location: "construction",
    birthday: 98,
    desc: "建筑工地的包工头，手上活多。关系好了会给好活。",
    birthdayLine: "哈哈，我今天生日，难得碰上你，请你喝瓶啤酒！",
    talkLines: ["今天活多，加紧干！", "小心点，安全第一。", "干得好有奖金。"],
    giftPrefers: ["cigarettes", "beer"],
    affinityRewards: [
      {
        threshold: 30,
