      "我这边有几个好工作，你要不要看看？",
      "做服务业态度最重要。",
      "多考几个证，好工作不愁。",
    ],
    giftPrefers: ["clothing", "snacks"],
    affinityRewards: [
      {
        threshold: 30,
        id: "sister_zhang_30",
        desc: "张姐透露内部招聘信息",
        effect: function (st) {
          const bonus = 200 + Math.floor(Math.random() * 300);
          st.resources.cash += bonus;
          st.resources.totalEarned += bonus;
