            st.skills[k].xp += 50;
          });
          StateManager.addMessage(
            "💕 张姐送了你一套证书备考资料，所有技能XP+50！",
            "success",
          );
        },
      },
      {
        threshold: 80,
        id: "sister_zhang_80",
        desc: "张姐帮你内推进入初级职场（加速进入P5）",
        effect: function (st) {
          st.flags.zhangReferred = true;
          StateManager.addMessage(
            "❤️ 张姐：「我认识个猎头，帮你递了简历，面试机会来了！进职场的路近了。」",
            "success",
          );
        },
      },
    ],
  },
  {
    id: "old_zhou",
    name: "老周",
    role: "收废品老人",
    location: "slum",
    birthday: 210,
    desc: "在城中村收了几十年废品的老前辈。知道废品行情的门道。",
    birthdayLine:
      "嗐，还是你记性好，我自己都忘了今天是我生日。岁数大了，每年过一年少一年呐。",
    talkLines: [
      "废金属最近涨了，赶紧多收点。",
      "收废品虽然脏，但也是一门生意经。",
      "年轻人脑子活，学学怎么挑好货。",
    ],
    giftPrefers: ["beer", "instant_noodles"],
    affinityRewards: [
      {
        threshold: 30,
        id: "old_zhou_30",
        desc: "老周分享废品行情密报（每日收废品+¥15）",
        effect: function (st) {
          st.flags.oldZhouTips = true;
          StateManager.addMessage(
            "💕 老周：「我告诉你，最近钢铁价格要涨，多囤点废铁。」废品回收效率大增！",
            "success",
          );
        },
      },
      {
        threshold: 60,
        id: "old_zhou_60",
        desc: "老周借给你一辆三轮车（扩大废品回收范围）",
        effect: function (st) {
          st.flags.oldZhouTricycle = true;
          StateManager.addMessage(
            "💕 老周把他的旧三轮车借给你，收废品的范围广了，效率提升！",
            "success",
          );
        },
      },
      {
        threshold: 80,
        id: "old_zhou_80",
        desc: "老周把废品站关系介绍给你（解锁高价收购渠道）",
        effect: function (st) {
          st.flags.oldZhouChannel = true;
          StateManager.addMessage(
            "❤️ 老周：「我干了三十年了，以后废品直接走我的渠道，价格比外面高三成。」",
            "success",
          );
        },
      },
    ],
  },
  {
    id: "xiao_mei",
    name: "小美",
    role: "大学生",
    location: "school",
