550	      handler: () => {
551	        const st = StateManager.getState();
552	        const isNewbie = st.player.day <= 10;
553	        // 烹饪技能减折扣：cooking 0→全价15, 50→9折, 100→3折（保底5元）
554	        const cookingLvl = st.skills.cooking.level || 0;
555	        const discount =
556	          typeof getCookingDiscount === "function"
557	            ? getCookingDiscount(cookingLvl)
558	            : 0;
559	        const baseCost = isNewbie ? 8 : 15;
560	        const foodCost = Math.max(5, Math.round(baseCost * (1 - discount)));
561	        if (st.resources.cash < foodCost) {
562	          StateManager.addMessage("⚠️ 钱不够吃饭了！", "danger");
563	          return;
